-- GENERATED by `wfj generate` from data/quest/quest-0095.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("quest", {
  [95033] = { "向こう側で", "FeralasのCamp MojacheにいるWitch Doctor Uzer'iと話してほしいとTan'janiは言っている。", "あのだだっ広い平原に飽きたんなら、俺の古い友達のUzer'iがいつも手伝いを探してるぜ。あいつはいつも魔法をこねくり回してるが、あいつがなかなかのハンターでもあるってことは、ほとんどの奴が知らねえのさ。\n\n興味があるなら、はるばるFeralasのCamp Mojacheまで行けば会えるぜ。\n\nこのTan'janiに言われて来たって伝えな。", nil, nil, 0x3c949346, 0x1f25c8c8, 0x1fc0fd3e, nil, nil, "...mm" },
  [95034] = { "借り", "SepulcherのLumina Windsingerと話してください。", "知っておいてほしいのだけど、道中で私たちを襲ったのは、実はGnollsではなかったの。\n\n実際に襲ってきたのは、狼のような巨大な生き物で、今では「worgen」だと知っているわ。そいつは護衛たちを片づけて私に向かってきたけど、Banonがその前に身を投げ出したの。私はなんとか呪文を放って驚かせ、追い払ったけれど、Banonはもうひどく噛まれていた。彼は自分を置いていけと言い張ったけど、私は拒んだわ。\n\n足を引きずりながらここへ戻る途中で、gnollに見つかったの。その後に起きたことは、恐ろしかった……", nil, "これで分かっただろう。gnollの刃に十数回も貫かれ、力尽きる寸前に、あいつは身を起こして私に襲いかかろうとした。その最後の瞬間、私たちは目を合わせた。あいつはまだ自分が誰なのか分かっていて、私のことも分かっているのが伝わってきた。何が起きているのか分かっていながら、自分ではどうにもできなかったんだ。それが何より辛かった。\n\nもしそんなことができるのなら、あいつを破滅させたあの獣を必ず仕留めて、二度と他の生き物にこんな恐怖を味わわせないようにしてやる。頭上の空にかけて誓う。", 0x0ff7705c, 0x84784026, 0xdc6412d7, nil, 0xb4f8e463, "...m." },
  [95036] = { "Moon-Kissedの刃", "SepulcherのTrevan Rolと話し、彼が必要とする材料を届けてください。", "Trevanによれば、worgenはSilverpine Forestの住民にとって大きな脅威だそうよ。強くてしぶといけれど殺すことはできる。でも、中に一体だけ、得体の知れない魔法のせいでどうしても死んだままでいない奴がいるの。\n\n私たちを襲ったのはそいつよ。Old Fire-Eyeと呼ばれていて、仲間の中でも一番大きくて凶暴な奴なの。あいつを仕留めるには、特別な武器が必要になるわ。\n\nTrevanと話して。そんな武器を鍛えるのに必要なものの一覧を渡してくれるはずよ。", "光があなたの刃を導いてくれると信じなさい。ですが、光にも導くに値する良い刃が必要なのです。", "必要な材料は揃ったから、あとは刃を打ってくれる鍛冶屋がいればいい。ちょうどいい鍛冶屋に心当たりがある。", 0xe7da37a4, 0x4585e62b, 0xb4f5a29b, 0x1c7078a4, 0xf4085685, "....." },
  [95041] = { "データの溜め込み屋", "Gnomeregan各地からGnomeregan Archival Dataのカードを7枚集め、IronforgeのJemma Quikswitchに届けてください。", "Gnomereganから逃げる前に、うちの一族の記録を紙に写しておいたんだ。奥義工学の場の方程式、Second Warの潜水艦の船体設計、Grandma Quikswitchのチリのレシピ……僕らの最高の業績があのファイルに詰まってる。\n\nIronforgeに着いてから、荷物に穴が開いてるのに気づいたんだ！ パンチカードが何枚かなくなってて、それがないとデータがめちゃくちゃで復元できないんだよ。\n\nカードはGnomereganの外のどこかで、雪に埋もれてるはずなんだ。探してきてくれないかな？ 望み薄なのはわかってるんだけど……", "データの回収は進んでいるか？", "このカード、少し湿ってるみたいだけど……まあ、これならなんとかなる！ ありがとう、{name}！", 0x2ec708ec, 0xdde3bae7, 0xd738032b, 0x4bbba72e, 0x87fa01c3, "....." },
  [95042] = { "Kor Gemを求めて", "AshenvaleのUlric FrostveilにKor Gemを持って行って下さい。", "Forsakenのパラディンが……このAshenvaleに？面白い。\n\nそれでKor Gemを求めているのか？驚くことでもない。Allianceのパラディンたちは、魔法の武器や道具を強化するのに時々これを使うからな。お前のような堕ちたパラディンが違うわけがあろうか？\n\n本当にその宝石の一つを望むなら、北のBlackfathom Deepsと呼ばれる遺跡へ向かわねばならない。今なおその宝石を使うnagaたちは地下にいる。一人で行くな、{class}。", "Korの宝石は大いなる悪行に使われることもある。お前の意図が清らかかどうか、私が判断することではない。私にはどうでもいいことだ。", "この宝石に染み込んだ穢れには、きっと気づくだろう。君の目的のためなら、nagaの魔女どもが宝石に注ぎ込んだ邪悪を払う魔法はごく単純なものだ。実に惜しいことだがね。こうした力からは学べることが多いのだから。\n\n宝石を探すきっかけになったクエストのことは忘れて、この宝石を私に売ってくれる気は……まあ、ないだろうね？ 私の……学術的な研究にとって貴重なものになりうるのだが。", 0x5d353131, 0x653f65b8, 0x34bb9815, 0x3e8b8507, 0x8c1b448d, "....." },
  [95059] = { "Frazzlespark's Crate", "Frazzlespark's CrateをFarholde KeepにいるKnight Commander Demar Brantに届ける。", "特別配達の時間だよ。\n\nFarholdeのKnight Commander Demar Brantがこれを待ってるんだ。なぜかあの人、いつも自分のフルネームを言わせるんだよね。変わった奴だよ。\n\nとにかく、ここから南西の砦にこもってるよ。でっかい石の要塞さ。見逃しっこないって。", nil, nil, 0x7845f90e, 0xa6cfa401, 0x826fc105, nil, nil, "...mm" },
  [95062] = { "Frazzlespark's Crate", "Frazzlespark's CrateをRog'marにいるKrom'roshに届ける。", "特別配達の時間だよ。\n\nここからすぐ西のRog'marで、Krom'roshのじいさんがこの荷物を待ってるんだ。\n\n早く、でも慎重に届けることをおすすめするよ。なぜかって？聞かないほうが身のためさ。", nil, nil, 0x7845f90e, 0x0463d5db, 0xa30e26ca, nil, nil, "...mm" },
  [95063] = { "Bloodmaster's Ring", "Bloodmaster's RingでBolder'okのBloodmasterであるChub'chobを倒し、Bloodmaster's Ringの新たな王者となった知らせをBolder'okにいるClugfistに伝える。", "よし、よく聞け。あんたはリングでなかなかの腕前を見せた。Chub'chobを言葉にできないほど怒らせちまったんだ。今あんたの立場じゃなくて本当によかったぜ。\n\n念のため言っておくが、参加料に事故死の補償は含まれてないからな。\n\n知り合えてよかったぜ。だが、ここから先は自力でやってくれ、あんた。\n\nせいぜい頑張りな。", nil, nil, 0xa5cbf621, 0x55ee5eb3, 0x93280971, nil, nil, "...mm" },
  [95064] = { "予防措置", "Terral's WatchにいるWatcher Corneliusのために、Rog'mar Traineeを$N1体倒す。", "オークどもは、やって来て以来ずっと迫りくる脅威だ。まずは川沿いの土地を奪い、今では平原でも勢力を広げている……\n\n奴らのことは決して理解できんし、正直なところ理解したくもない。だが、まだ奪える土地があると思っているなら、そうはさせるものか。", nil, nil, 0x5d319cbd, 0x0c83fe90, 0x9ffbbadf, nil, nil, "...mm" },
  [95065] = { "釣りの時間だ", "Shiny Baubleを$N1個とNightcrawlersを$N2個、Stormwindの港にいるGilbert Grayのところへ持って行ってください。", "なんという眺めだ……老いぼれが望める最高のものだよ。\n\n今は魚がよく食いついているんだが、餌がもう最後なんだ。まさか釣り道具の予備なんて持っていないだろうね？ いや、もちろんないよな、すまない。もう一度糸を垂らすことを考えたら嬉しくなって、どこへ行くにも道具を持ち歩く者なんてそうはいないってことに思い至らなかったよ。\n\n在庫の補充を手伝ってもらえないかな？ Catherine Lelandが、運河沿いのTrade Districtのすぐ西でいろいろな釣り道具を扱っている。老いぼれのGrayの使いだと言ってくれ。", "釣り道具は手に入れたか？", "いいところに来たな！ 最後の餌で大物を釣り上げたところだ。今日はここまで上々だよ。ここはよく食いつくんだ！\n\nそうだ、このじいさんの商売を助けてくれたお礼に、道中用に魚を何匹か持っていかないか？", 0x50ff1618, 0x1ca3ae56, 0x4f6c7d2d, 0x630eca56, 0x7cc547b8, "....." },
  [95066] = { "Rog'marの情勢", "報告書をFarholde KeepにいるDemar Brantに届ける。", "我々が届けたメッセージは明白だ。\n\n砦の中のBrantのもとへ戻り、報告書を見せてくれ。きっと我々の進展を喜ぶはずだ。", nil, nil, 0x6e3e67b7, 0x9da61674, 0x1a83c1a3, nil, nil, "...mm" },
  [95111] = { "過小評価された才能", "Ottと話し、あなたの剣を鍛えてくれるよう頼む。", "Tarren MillにはOttという武器鍛冶がいる。誰に聞いても、旅人に簡素な剣を売るだけの平凡な鍛冶屋だそうだ。私も彼から剣を一振り買ったのだが、しばらくして手入れのためにUndercityへ持っていくと、そこの鍛冶屋たちがその出来に驚いていた。名の知れた名工の作だと思い込んでいたが、違う、それはただのOttだったのだ。\n\nこのオークに、本当に特別な仕事をする機会を与えたい。材料をTarren MillのOttに届けて、依頼を申し出てくれ。", "剣が入り用か、{class}？", "面白い。実際に特注の仕事を頼まれたことなんて、たぶん一度もないな。たいていは自分のやり方で、質素で実用的な武器を作っているだけだ。大したものじゃないが、まっとうな仕事だし、称賛や栄光を求めてもいない。\n\n喜んでやってみるが、なぜ俺のところに？ Undercityには、こういう特注の仕事を引き受ける鍛冶屋がいくらでもいるぞ。", 0x2c5a8af0, 0x57d2ed34, 0x9137acf7, 0x45d644e4, 0xc6b81f00, "....." },
  [95118] = { "海の荒くれ者", "Eastwind Shore沿いで、Murloc Oracleを8体とMurloc Warriorを8体倒す。", "murloc、murloc、murloc！聞こえてくるのはそればっかりだ。船乗りからも、漁師からも、うちの子供たちからもな！みんなして奴らのことで俺にうるさく言ってくる！確かに厄介者だけどさ、俺はここで港を切り盛りしなきゃならないんだよ！\n\nちょっと助けてくれないか？あいつらを何匹か倒してくれたら、それなりの礼はするよ。", nil, nil, 0xb5ac9836, 0x3b93d4ea, 0x6546b7aa, nil, nil, "...mm" },
  [95119] = { "手荒な商売敵", "Powderfuse Portの北のEastwind Shore沿いで、Eastsea Buccaneerを$N1体とEastsea Musketeerを$N2体倒す。", "Eastseaの一味を知ってるか？本当にろくでもない連中だ。しかもそれを言ってるのは、「Powderfuse Port」なんて名前の場所を仕切ってる男だぜ。\n\n奴らは破壊的で、血に飢えてて、何より最悪なのは、俺の儲けを削ってることだ！積み荷は盗むわ、船は沈めるわで、どっちも結局は大金がかかるんだよ！\n\n奴らの組織をまるごと潰さなきゃならない。まずは一番近くにいる奴らからだ。北の浜辺沿いにいるぞ。", nil, nil, 0x4b93ed2b, 0xf0a3a238, 0xd3a43092, nil, nil, "...mm" },
  [95120] = { "お尋ね者：Old Rot-Chum", "Old Rot-Chumを倒した証拠をWharfmaster Whizzbuzzのところへ持って行く。", "船乗りと泳ぐ者は注意せよ！地元の漁師たちから「Old Rot-Chum」とあだ名をつけられた特に凶暴なmurlocが、南の海域、murlocがはびこる島々の近くで、手漕ぎボートやその他の小舟を襲っているのが目撃されている。\n\nこの生き物が死んだ証拠と引き換えに、Wharfmaster Whizzbuzzが報酬を出している。", nil, nil, 0x41ad0257, 0xe060fa56, 0x8fcb05bb, nil, nil, "...mm" },
  [95121] = { "海の味", "Fimbo Greasemitzのために、Murloc Eyeを12個とSand Crawler Meatを6個集める。", "Fimboの水上カフェへようこそ！本日のメニューは、猪の丸焼きと魚の丸焼き……毎日同じだけどな……\n\nこのメニューは本気で変えなきゃいけない。新しいシーフードシチューのレシピに目をつけてるんだが、新鮮な肉が必要なんだ。murloc eyeをいくつかと、カニの肉が少しあれば足りるだろう。\n\nどっちもこの近くの浜辺で見つかるよ。昔ながらの地元の食材にはかなわないからな！", nil, nil, 0x424dd627, 0x56371c30, 0x34fec1a6, nil, nil, "...mm" },
  [95122] = { "野放しの拡大", "Wharfmaster Whizzbuzzのために、Eastsea Raiderを$N1体とEastsea Bombardierを$N2体倒す。", "あんたがぶちのめしたEastseaの海賊どもは、危険ではあったが、ほんの小物にすぎない。ここから北には、もっとでかくて凶悪な仲間がいるんだ。奴らはWindsteadを荒らし回った。奪えるだけの略奪品を奪って、それから焼き払っちまったんだ。\n\n奴らの縄張りがこれ以上内陸に広がる前に止めなきゃならない。そうならないように、奴らの数を減らしてくれ。", nil, nil, 0x8e943689, 0xf053b390, 0x2291e4d1, nil, nil, "...mm" },
  [95123] = { "一発食らえ、ろくでなしども！", "Wharfmaster Whizzbuzzのために、Eastsea Powder Kegを$N1個盗む。", "Eastseaの連中の首が飛ぶのを見るのは大好きだが、奴らの船も始末しなきゃならない。増援を呼びに逃げられちゃ困るだろ？\n\nそれについては計画があるんだが、火薬が必要だ。それも大量にな。\n\n海賊どもは、北の破壊されたばかりのWinsteadの近くに火薬をいくらか保管してるはずだ。手に入れられるか見てきてくれ。残りの話はあとでするよ。", nil, nil, 0x36103d46, 0x7a2e25da, 0x60929911, nil, nil, "...mm" },
  [95124] = { "Admiral Lamora", "Admiral Lamoraを倒して奴の隠した戦利品を見つけ、Wharfmaster Whizzbuzzのところへ持ち帰る。", "さあ、いよいよ親玉本人を追う時だ。Admiral Lamoraだ。当然、奴には死んでもらいたいが、それとは別にちょっとしたものも頂きたい。\n\n奴の略奪のせいで俺は大損してるんだから、損失をいくらか取り戻すのが筋ってもんだろ。\n\nLamoraはここから北東にあるEastseaの船のどれかに乗ってる。どの船で、船のどこにお宝をしまってるのか突き止めてくれ。奴が持ってるものは何でも持ってこい。鍵がかかってるなら、たぶん奴が鍵を持ってるはずだ。", nil, nil, 0x7f2fde5c, 0xbe87cf02, 0xb7aa8e23, nil, nil, "...mm" },
  [95125] = { "Ott's Masterwork", "Ottがあなたの剣を鍛えるのを見届ける。", "これは実に見事な素材だな、{class}。この剣を鍛えさせてくれるとは光栄だ。期待に応えられるといいんだが。\n\nさあ、少し下がっていてくれ。鍛造を始めるからな。", nil, "この刃は俺の最高傑作だ。旅の役に立ってくれることを願っている。この機会を与えてくれて、改めて礼を言う。\n\nAka'Magosh、友よ。", 0x2af2ae36, 0xa5330aaf, 0xa0a0368f, nil, 0xee452c14, "...m." },
  [95126] = { "Moonsilver Blade", "Ott's MasterworkをSilverpine ForestのTrevan Rolに届ける。", "これが剣だ。Trevanという名のパラディンに言われて来たと言ったな? 今度会ったら、この機会をくれた礼を伝えてくれ。誇りを持って行け、友よ。", "Ottは依頼を果たせたか？", "<Trevanは刃を受け取り、注意深く調べる。>\n\nこれなら申し分ない、{name}。Ottには本当に素晴らしいものを作る力があると分かっていたよ。\n\n残るはあの獣を仕留めることだけだ。準備ができたらLuminaと話してくれ。", 0x774c6075, 0xb9d5e27a, 0xac0b5a01, 0xaf39b5e9, 0x469d97a1, "....." },
  [95140] = { "Old Fire-Eye", "Moonsilver Bladeを使って、Silverpine ForestのOld Fire-Eyeを倒して下さい。", "武器を手に入れたようだな、{class}。それがお前を裏切らぬよう祈っている。\n\n地元の者の話では、Old Fire-Eyeはここから南の広い範囲で狩りをしていて、たいていはGilneasの門の近くで見つかるそうだ。奴を見つけ、新しい剣で仕留めてくれ。それが済んだら戻ってこい。Windshaperたちの感謝を受けるだろう。", "済んだか？獣は倒されたか？", "ありがとう、{name}。これでBanonも安らかに眠れるでしょう。\n\nもし許してもらえるなら、血を浴びたばかりのあなたの刃に魔法を授け、私たちの民の魔法をほんの少し宿らせることができると思います。\n\n<Lumina Windsingerの目が鮮やかな青に輝き始め、彼女はあなたの手にある血に染まった刃に触れる。>\n\n終わりました。ささやかなものです。これほど見事な刃を私が良くすることなど、ほとんどできませんから。それでも、この刃があなたの役に立つよう風に祈ります、{class}。", 0x1db24010, 0xee598827, 0x2f1bb8e0, 0x95a43f2e, 0xb76eccca, "....." },
  [95141] = { "Rog'marへの報告", "RivergladesのRog'mar前哨地にいるKrom'roshに報告する。", "Stonardのはるか北東、東の海岸沿いに、Rivergladesと呼ばれる戦乱の地がある。\n\n多くの者がこの地を手に入れようとしたが、成功した者はほとんどいない。だが、敵との戦いの経験によって、Rog'marという小さな前哨地を築くことができた者が一人いる。数え切れない攻撃を受けながらも、そこはいまだに持ちこたえている。\n\nKrom'roshは冷酷な男かもしれんが、その意志は我らの同盟者に大いに役立ってきた。戦いを求めるなら、北東へ向かい、我らの古い友を訪ねるがいい。", nil, nil, 0xace9c387, 0x34de9fdc, 0xe783d97b, nil, nil, "...mm" },
  [95143] = { "Tan'janiを探して", "RivergladesのRog'marでTan'janiを見つける。", "見てたぜ、{name}。お前はこの辺りでうまくやってる。俺の兄弟、Tan'janiを探すのを手伝ってくれる気はないか？\n\nあいつはいつも何かを探してた。何をかは知らねえ。あいつが出て行ってから、知らせを2通受け取った。最初のは別の旅人からで、Loch Modanの南のどこかでTan'janiに会ったって知らせだった。二通目は血まみれの手紙で、Rivergladesと、さらに南のRog'marって場所のことが書いてあった。残りは読めなかった。\n\nあいつを見つけられそうか？", nil, nil, 0x5f1d7210, 0x85b64451, 0x30ffd973, nil, nil, "...mm" },
  [95144] = { "海外への配達", "Fizzgrimble's Mysterious CrateをRivergladesのPowderfuse PortにいるFriz Frazzlesparkに届ける。", "よう、あんた。俺の古い友達に届けてほしい荷物があるんだ。何があっても……\n\n荷物は絶対に開けるな！\n\nこいつを、慎重に、海の向こう、Rivergladesにある俺たちの姉妹港のFriz Frazzlesparkのところまで持っていってくれ。あと、聞かれる前に言っとくが、泳いでいくのはおすすめしない。前の奴はうまくいかなかったからな。ああ、それと、傾けたり、振ったり、急に動いたりするなよ。\n\n東のSteamwheedle Portへ行くのがおすすめだ。そこから出る船なら、たいてい安全に渡れる。\n\n幸運を祈るぜ！", nil, nil, 0x69392ac7, 0xd1577f7c, 0xce15a97d, nil, nil, "...mm" },
  [95147] = { "行方不明の斥候", "Bolainの伝言をSouthern WatchにいるCaptain Daltonに届ける。", "お前……どこから来た？ここにいちゃいけない！\n\n<Bolainは痛みに耐えている。傷だらけで打ちのめされ、脚には病に冒された噛み傷がある。>\n\nこれをDaltonに届けてくれ。道を北へ上って、それから東だ。俺の脚のこのひどい傷よりも平原が大きく開けている所だ。あいつが正しかったと伝えてくれって言いたいところだが、あいつにそんな満足感をくれてやるもんか……少なくとも俺が死ぬまではな。\n\nこのクソったれな丘が大嫌いだ！", nil, nil, 0xb3678d9a, 0xc6cc93b8, 0xd0ee412a, nil, nil, "...mm" },
  [95148] = { "Southern Watch Gnoll Report", "Southern Watch Gnoll ReportをFarholde Keepの騎士団長に届ける。", "この血まみれの知らせを騎士団長ご本人に届けたいのは山々だが、自分の持ち場も守りたいんでね。少しきれいにしておいたから、それほど……まあ、血まみれじゃなくなった。\n\n最近gnollの反乱が続いているから、悪いがこの知らせを届ける役目はあんたに回ってくる。", nil, nil, 0x850d7dbd, 0x75b74caf, 0xb4923963, nil, nil, "...mm" },
  [95156] = { "詰め込んで突き刺せ", "訓練場にいるEmberのために、Bundle of Hayを$N1個集める。", "訓練用の人形がかなり傷んできている。すぐに直さないと、新兵たちが戦いへの備えができないのではないかと心配だ。\n\n来る途中で見かけなかったかもしれないが、砦のすぐ外にWheelerという男がやっている小さな農場がある。分けてくれる干し草が何束か余っているかもしれない。\n\n我々のために物資を分けてもらえるなら、彼にはきちんと補償するようにしよう。", nil, nil, 0x25a2dad2, 0x3edfe8e2, 0xb9cc71e2, nil, nil, "...mm" },
  [95161] = { "愛していると忘れないで", "Blood-Stained LetterをDuskwoodのAvette Fellwoodに届けてください。", "Jeremy Heartweaverを探しているなら、一番いいのは、Duskwoodにいる彼の新しい養母、Avette Fellwoodに話を聞くことだね。優しい人だよ。仕事の人手がもう一人ほしいんだろうけど、孤児院にいるよりはましだろう。\n\nもし小さなJeremyに会ったら、みんなあの子のことを思っているって、ちゃんと伝えてくれるかい？", "何だ？何が要る？", "ああ、そんな……\n\n持ってきてくれたのはありがたいけれど、Jeremyにはまだ見せられないと思うわ。Matron Nightingaleの話では、うちのJeremyはLordaeronが襲われてから一言も話していないそうなの。今、無理をさせるつもりはないわ。これを見せたら、あの子をもっと苦しめるだけよ。\n\nそんな目で見ないで。あの子の過去を隠すつもりはないけれど、癒えるには時間が必要なの。大きくなったら渡すわ。来てくれてありがとう。でも、もう帰ったほうがいいと思うわ。", 0x920a601f, 0xa5aac85c, 0xab5e3e2b, 0x664e4a5c, 0xbb9d2166, "....." },
  [95162] = { "Paletusk集め", "Bolder'ok近くにいるNa'zokのために、Chunk of Boar Meatを$N1個集める。", "人間やTwilight's Hammerに奪われていない土地がこれほど少ない中で、この牧場は俺たちにとって数少ない食料源の一つだ。ogreは農夫向きじゃないが、paletuskの丸焼きには目がなくてな、肉が届き続ける限り俺がここにいてもいいと言ってくれた。\n\n戦争が進むにつれて、食料の需要は増える一方だ。今じゃ、ogreどもが俺を次の食事みたいな目で見ないようにするだけの食料もろくにない。\n\nRog'marのために十分な肉を確保したいなら、収穫を手伝ってもらう必要がある。", nil, nil, 0xf781fc8d, 0x7dc71fe6, 0x4717ae1f, nil, nil, "...mm" },
  [95163] = { "奴らを押し返せ", "Young Paletuskを$N1頭、Bolder'ok近くのNa'zokの農場へ連れ戻す。", "見ての通り、囲いの中よりも谷に散らばっている豚のほうが多い。Gorgegutは理想的な農場の手伝いとは言えないが、人間どもを寄せつけないでいてくれる。\n\n小さいのが何匹か川の向こうへ逃げちまった。まだ小さすぎて現地では収穫できないから、ここへ連れ戻さなきゃならない。この棒を持っていって、しっかり叩いてやれ！そうすれば慌てて囲いへ駆け戻るはずだ。", nil, nil, 0xa0591727, 0x318c14ec, 0x3b0017c3, nil, nil, "...mm" },
  [95165] = { "あばよ、悪党ども！", "Eastseaの3隻の船それぞれに遠隔爆薬を仕掛ける。", "さて、あの船をどうやって沈めるか説明するぞ。\n\nあんたが盗んできた火薬を使って、時限爆薬を作れる。あんたはEastseaの船に一隻ずつ乗り込んで、それぞれの船体に爆薬を1つ仕掛けるだけでいい。大砲の近くの場所を探してくれ。あそこの火薬で、俺たちの爆薬がさらに強力になる。爆薬を仕掛けたら、さっさと逃げろ。そしたら俺が起爆装置を押す！\n\nこの計画の美しさはその単純さにあるんだ、そう思わないか？", nil, nil, 0x44b992a0, 0x7579e8e1, 0x23f954ec, nil, nil, "...mm" },
  [95183] = { "第一段階：石", "Bolder'okにいるHamurのために、Good Rockを$N1個集める。", "お前、ogreの武器欲しい？俺、ダメってわかる。お前小さい。うまく持てない。\n\nお前、Hamurにもっとrock持ってくる。俺、お前に小さい武器作る。小さい生き物にいい。\n\nいい武器のため、good rock探せ。Hamur、目が肥えてる。どんな石でもいいわけじゃない。Bolder'okの外の川の近くでrock探せ。", nil, nil, 0x84960ab5, 0x839322c3, 0x51d160bd, nil, nil, "...mm" },
  [95184] = { "最も鋭い刃", "Solid Sharpening Stoneを$N1個、Farholdeの訓練場にいるEmber Bladewhisperのところへ持って行く。", "戦いの訓練の厳しさはまた別の話だが、ここの訓練生たちは、訓練用の剣と歴戦の古参兵がよく手入れした刃との違いをまだわかっていない。\n\n研ぎ澄まされた刃が勝利と死の分かれ目になりうることを、新兵たちに見せてやる時だと思う。\n\nsharpening stoneをいくつか見つけてきてくれたら、有効に使わせてもらう。この技術を学ぶ職人がいると聞く。まずはそこから当たってみるといい。", nil, nil, 0xa2463757, 0xba047dbd, 0xab9be8a8, nil, nil, "...mm" },
  [95189] = { "Crest of Lordaeron", "Crest of LordaeronをStormwind CityのLady Dena Kennedyに返してください。", "<Lordaeronの紋章が描かれた、風雨にさらされた紋章だ。王国の滅亡後に残った遺物はごくわずかなので、Stormwindの誰かがぜひとも手に入れたがるだろう。>", nil, nil, 0x98ec1516, 0xea3f7a39, 0x6f2a4873, nil, nil, "...mm" },
  [95195] = { "Bloodied Insignia", "Bloodied Insigniaを$N1個集め、Stormwind CityにいるGeneral Marcus Jonathanのところへ持って行ってください。", "<この古いAllianceの記章は、Lordaeronの兵士のものだったようだ。この遺跡には、きっと同じような勲章がたくさん眠っていて、生きている身内は返してもらえればありがたく思うだろう。>", "重い荷を背負っているように見えるな、{name}。どうしたのだ？", "これを私のもとへ持ってきたあなたの直感は正しかった。LordaeronがScourgeの手に落ちたとき、多くの人々がここStormwindへ逃れてきた。自らこの記章を受け取りに来られる者は、もうほとんど残っていないだろう。\n\nStormwindへの務め、見事だ、{name}。すぐにこの記章を近親者たちに配り始めよう。", 0xfb70dfc5, 0xf9dfef5a, 0x2c958367, 0x3d6daf5e, 0x351f4fdf, "....." },
  [95204] = { "Crest of Lordaeron", "Crest of LordaeronをUndercityのOran Snakewritheに届けてください。", "<Lordaeronの紋章が描かれた、風雨にさらされた紋章だ。王国の滅亡後に残った遺物はごくわずかなので、Undercityの誰かがぜひとも手に入れたがるだろう。>", "そこに何を持っているんだ、{class}？うまそうな一口か？", "<Oranは本物かどうか確かめるために紋章をかじる。>\n\nこいつは驚いた。故郷の本物の遺物だ。ほとんど傷もない。こいつは特に慎重に扱わないとな。\n\n我々の歴史を取り戻す手助けをしてくれてありがとう、{class}。こいつは責任を持って大切に保管するよ。", 0x98ec1516, 0x937c7b4b, 0x992e7722, 0x059931e7, 0xc46da411, "....." },
  [95212] = { "鞍に妥協なし", "Pristine Leopard Peltsを6枚集め、Amberstill Ranchに届けてください。", "Alterac遠征隊の増援に雄羊の隊を送る準備をしているんだが、鞍を作る材料が切れてしまったんだ。\n\n東にいる一番大きくて獰猛な豹の毛皮を集めて持ってきてくれ。あそこは身を切るような寒さだ。我らの部隊には、暖を取るための最高の毛皮こそふさわしい！", "寒そうだな、{class}。狩りの調子はどうだ？", "この毛皮なら上等な鞍ができる。Allianceの誇りだぞ、{class}！", 0x07df31f7, 0x270babaf, 0xb5c3ab85, 0x545929d0, 0xcdcfccf7, "....." },
  [95213] = { "Stolen Blasting Powder", "Empty Powder KegをGol'Bolar QuarryのQuarrymaster Thestenに届けてください。", "樽には刻印がある。\n\n発破用火薬 - 危険 - 取扱禁止 - 危険 - 採石場長の許可者のみ - 危険\n\ntroggがこれを持っているべきではないという嫌な予感がする。できるだけ早く採石場に報告した方がいいだろう。", "何を持っているんだ？", "<空の樽を見て、ドワーフの顔が青ざめる。>\n\n……これをどこで見つけた？", 0x8848eca5, 0xd56ef55e, 0xf1f411df, 0xac2369a3, 0x28899f23, "....." },
  [95214] = { "Stolen Blasting Powder", "Gol'Bolar Quarryの東にいるtroggからStolen Blasting Powderを$N1個取り戻し、Quarrymaster Thestenのところへ戻ってください。", "この樽には、King Magniの玉座の間を吹きさらしの中庭に変えてしまえるほどの火薬が入っていた。troggどもが火のつけ方に気づく前に、取り返さなきゃならん。", "良い知らせを持ってきてくれたんだろうな？", "これで盗まれた火薬は全部のはずです。ありがとうございます、{class}。\n\nこの報酬を受け取ってください。それと……このちょっとした一件は、誰にも言わないでいただけるとありがたいです。", 0x8848eca5, 0x4fe59366, 0xcc857a5c, 0xb50481e8, 0xad0053e0, "....." },
  [95216] = { "新たな疫病", "UndercityのTheodore Griffsのために、Ruins of LordaeronのWitherfangからHighly Toxic Strainを手に入れてください。", "Undercityで最も重要な臓器、The Apothecariumへようこそ！ ここではAzerothの珍しい標本の中でも最も毒性の強いものを使って実験しているのです。\n\n今は機嫌がいいので、私の最新の研究について教えてあげましょう。どうやら、我らが麗しき街の上の廃墟に、特に毒の強い節足動物がうろついているらしいのです。その毒はアンデッドの肉さえも溶かすと言われています。なんと胸躍ることでしょう！\n\nこの話を確かめたいのです。もしその咬み傷で体が朽ちていくようなことがあれば、ぜひ見本をいただきたいですね。", "最も強力な感染経路は常に血液だ、そんなことは愚か者でも分かる。\n\nこの菌株を自分の目で確かめねばならん！", "殺しただと？？\n\nふん。運のいい奴め、これだけの体液があれば、その性質を逆解析できるはずだ。Royal Apothecary Societyを敵に回したくはないだろう。\n\n私の前から消え失せろ！", 0xbf7a7e24, 0xec263960, 0x9214d563, 0x5c8c63f0, 0x8f9e0d7b, "....." },
  [95217] = { "採石場の鍛冶屋", "Copper Barsを12本とToughened Boar Hidesを4枚集め、Frast Doknerに届けてください。", "鍛冶屋の仕事を学びたいってのか？ だったら、お互い助け合えるかもしれないな。\n\n補給品の輸送が遅れていて、野営地のあちこちを修理する材料が要るんだ。必要なものを持ってきてくれたら、俺の技をいくつか教えてやろう。悪くない話だろ？", "怠けるなよ、{name}。鍛冶は怠け者には務まらんぞ！", "なかなか機転が利くな、{name}。\n\nさあ、よく聞け。二度は言わないぞ！", 0xcf9ba453, 0x56fdeb4f, 0xd3803ca1, 0x8461c8b8, 0x9e396b99, "....." },
  [95219] = { "港から港へ", "Cask of Powderfuse PortをFeralasのFeathermoon StrongholdにいるMardrack Greenwellに届ける。", "また仕事があるよ、あんた。世界を旅するのはどうだい？\n\nこいつは、あんたが見たこともないような極上のポートワインさ。問題は、はるばるFeralasのFeathermoon Strongholdにいるお客さんのところまで、かなりの距離を運ばなきゃならないってことでね。見たこともないほど高い木のところに着いたら、そこが目的地だよ。\n\nうちの者が密閉して詰めたけど、何がきっかけで爆発するかわかったもんじゃない。だから取り扱いには注意してね、いいかい？", nil, nil, 0xd8171350, 0xa90a2a71, 0xf2c5517c, nil, nil, "...mm" },
  [95250] = { "忌まわしき怪物", "Ruins of LordaeronでHead of the Baronを手に入れ、Captain Trumanのもとへ持ち帰ってください。", "何の用だ、{race}？ 勝たねばならん戦があるのが見えんのか？\n\n主人はすでに戦いのただ中へ突撃していき、私には持ち場を守るよう命じられた。だが、もうかなりの時間が経っている。\n\nお前が戦場で10分も生き延びられるとは思えんが、その単純な頭の暇つぶしになるなら、Grand Marshalを探してみたらどうだ。お前がこれまで目にした中で最も背が高く、最も堂々とした英雄だ。見ればすぐにわかるだろう。", nil, nil, 0x83266151, 0xb8e0ac06, 0x0f67af09, nil, nil, "...mm" },
  [95254] = { "お尋ね者：Trapclaw", "Trapclaw's PincerをFimbo Greasemitzのところへ持って行く。", "釣り人の皆さんへ！\n\nカニの肉を求む。それもいつもの細切れじゃなく、ハサミまるごとだ。桟橋の下を大きいのが這い回って、餌を盗んだり糸を切ったりしているのを見かけた。\n\nそいつのpincerを持ってきてくれた人には報酬を払う。私が作る料理も一皿ごちそうしよう。\n\n-- Fimbo Greasemitz", nil, nil, 0x7381e71b, 0x0715343f, 0x71e25cae, nil, nil, "...mm" },
  [95260] = { "深海からの恐怖", "絵の描かれた皮から怪物の正体を突き止められる人物を、Powderfuse Portで探す。", "皮には魚のはらわたとイカ墨で大きな筆跡が描かれている。波間からせり上がる、長い首を持つ海の怪物のようなものが描かれているようだ。この獣はいったい何なのだろうか？\n\n一番近い港はPowderfuse Portだ。この怪物が実在し、この海域に潜んでいるのなら、そこの船乗りがきっと見ているはずだ。", nil, nil, 0xc41fb262, 0x788e0d2d, 0xeaff074d, nil, nil, "...mm" },
  [95261] = { "肝が要る", "Argo Brinewhistleのために、Beast Entrailsを$N1個とRotflesh Mushroomを$N2個集める。", "あの怪物……首の長い、あんたが言ったとおりのやつだ。あの島の辺りで見たことがあるんだ。俺の船で沖に出てた時にな。みんなにヒック、話そうとしたんだが、いやいや、だーれもヒック、このArgoの言うことなんか信じちゃくれねえ。ただの……ただの……酔っ払いの漁師だってよ！作り話だってな！\n\n見返してやるさ……餌さえ手に入れば……\n\nおい！突っ立ってんじゃねえ！entrailsがいるんだ、それも大量にな。この辺りの獣なら何でもいい。臭けりゃヒック、臭いほどいい。それと、Rotflesh mushroomもいる。Windsteadのそばのあの洞窟に生えてるんだ。", nil, nil, 0x7e4cdee7, 0x6b5ebde3, 0x374f563e, nil, nil, "...mm" },
  [95267] = { "怪物、浮上", "Big Ball o' Baitを使って海の怪物をおびき出す。その後、その首をArgo Brinewhistleのところへ持って行く。", "最後の仕上げはヒック、簡単だ……あのでっかい内臓の玉を持って、水にぶん投げるだけさ！えっと……ここじゃねえぞ……そんなことしたら大惨事だ。\n\nあのヒック、murlocの島へ行け、あんたが絵を見つけた所だ。水に浮かんでる新しい残骸を探せ。そこに餌を投げるんだ。\n\nあいつが頭を出したら、すぐに切り落とせ！そいつで飾りを作るんだ……船のな！", nil, nil, 0xb7adbfe6, 0x54805005, 0xb146a9e4, nil, nil, "...mm" },
  [95288] = { "密輸業者の楽園", "Powderfuse PortにいるFriz Frazzlesparkのために、Smuggled Goodsを$N1個集める。", "あんた、人に言われたことは何でもやる癖がついてるように見えるね。手下としてはそういうのが好きだよ。ちょっと鍛えれば、すごい戦力になるかもね。試してみようじゃないか。\n\n最近、あのEastseaの海賊どもが、私の盗品の積み荷を持ち逃げしたんだ。スポーツマンシップに反するね。先に盗んだのは私なんだから！\n\n教訓その1だよ、手下くん。裏切り者を背後から刺すような真似はするな。奴らに、ちょっかいを出す相手を間違えたゴブリンだって思い知らせて、私の物を取り返してきな。できれば力ずくでね。", nil, nil, 0xacce94e6, 0x0ef2467a, 0x34e26573, nil, nil, "...mm" },
  [95293] = { "密輸業者の特製品", "The Friz SpecialをEastwind ShoreにいるCaptain Bentcoinに届ける。", "あんたがEastseaの海賊から取り返した品は、まっすぐ私のところに送られるはずだったんだ。つまり、Bentcoinの奴が私の縄張りに割り込めると思ってるってことさ。どうやら貿易戦争を始めるつもりらしいね。でも、私たちは文明人だ。\n\n教訓その2だよ、手下くん。奴らのレベルまで落ちる必要はない。あの立派な船長のために特別に作ったこの木箱を持っていきな。奴はEastwind Shore沿いの自分の船にいるよ。抜け目のない交渉術へのご褒美をあげなきゃね。", nil, nil, 0xb7c0cc5c, 0x09eb355f, 0xf241038e, nil, nil, "...mm" },
  [95294] = { "密輸業者の取引", "Powderfuse PortにいるFriz Frazzlesparkのところへ戻る。", "Frizは言いたいことの伝え方をよく心得てるな。まあ、俺から文句を言うことはねえよ。Eastseaの海賊は彼女の商売に手出ししない。その代わりに、何か取り決めができるかもしれねえ。恨みを抱いたゴブリンに一日中略奪好きの冒険者をけしかけられちゃ、海賊稼業もちょっと難しいからな。\n\nさっさと主人のところへ帰りな、{class}。Frizに伝えてくれ。新しい船長が仕切ることになった、そいつは俺たちの将来に儲かる関係を見込んでるってな。", nil, nil, 0xdfdbe23f, 0xc86a92fb, 0xf74a396c, nil, nil, "...mm" },
  [95295] = { "知り合いがいる", "Booty BayにいるFrizの連絡相手と話す。", "海賊どもの件はよくやったね、下っ端。でも、覚えておいたほうがいい教訓を教えてやるよ。ある者が海賊と呼ぶものを、別の者は私掠者と呼ぶ。そして私掠者って言葉には「タダのお宝」が入ってるのさ。タダのお宝なら、Booty Bayほどいい場所はないよ！\n\n<Frizはあなたの返事を待っている。>\n\nちゃんとついてきなよ、ひよっこ。つまり、Booty Bayに行って私の連絡係に会ってほしいってこと。そいつは地元の海賊、いや、私掠者から品物を仕入れてるんだ。いいかい、とにかくRuzzgotを探しな。残りはあいつが説明してくれるよ。", nil, nil, 0x21e479e5, 0xe3d0d2e8, 0x81b82ccb, nil, nil, "...mm" },
  [95296] = { "発送と取り扱い", "TanarisのSteamwheedle PortにいるWharfmaster Steamfizzleと話す。", "次の授業の準備はできてるみたいだね、チャンプ。私はこの町で自分の交渉ごとがあるから、忙しい間にいくつか使いを頼みたいんだ。\n\nやってほしいのは、あそこの波止場から次の船に乗って、この木箱をSteamwheedle Portの仲間に届けることだけさ。\n\nそんな顔しないでよ。きっと十分わくわくするって。ゴブリンに借りを払わせるのは、地元のごろつきを痛めつけるよりずっと難しいんだ。税関を通るのは言うまでもなくね。まあ、なんとかなるさ。", nil, nil, 0x2df4f691, 0xf45e87c6, 0xaf23f96a, nil, nil, "...mm" },
  [95312] = { "取り立てに来た", "GadgetzanにいるFizbuz Mithrilと話す。", "Frizの金は持ってないよ。いや、彼女の金は持ってたんだけど、GadgetzanのFizbuzの闘技場で、あのSlugjawに全部賭けちまったんだ。\n\nそんな顔するなって。堅実な投資だったんだ。大勝ちしたんだぜ！ただ、まだ賞金を受け取りに行く暇がなかっただけさ。Frizの新しい使い走りなら、代わりに取ってきてくれないか？ほら、俺は腰が悪いんだよ。\n\nなあ、手ぶらでボスのところへ戻りたくないだろ？Gadgetzanはここのすぐ西だ。見逃しっこないよ。", nil, nil, 0x1b965496, 0xf77b0d34, 0xd1b29959, nil, nil, "...mm", nil, nil, 0xa59e9499, nil, nil },
  [95314] = { "あのShadowvaleの緑の霊薬", "ShadowvaleでBottles of Whispering Elixirを$N1本集め、BrillにいるCarolai Aniseのところへ戻ってください。", "Scourgeの侵攻以前、人里離れたShadowvaleの村はWhispering Elixirで知られていた。Tyr's Fallにしか生えない薬草から蒸留されたその霊薬は、街で禁じられた後でさえ、薬師や神秘家、毒使いにまで求められていたんだ。\n\n何人もの買い手から、その霊薬が欲しいと頼まれている。西のWhispering Forestの奥深くにあるShadowvaleの廃墟へ行ってくれ。何本か取り戻してくれたら、たっぷり報酬を出す用意がある。", "道に迷わなかっただろうな？", "Shadowvaleに邪悪なものがいるだと？ 正直、驚きはしない。森の民は風変わりな連中で、よそ者を好まなかった。Whispering Forestそのものが呪われていると信じる者もいるし、その根から蒸留した霊薬にも同じ呪いがかかっているという……\n\n……だが迷信や噂の話はもう十分だ、{name}。霊薬をありがとう。ほら、代金としてこれを受け取ってくれ。", 0x62c6b7bf, 0xff6777a1, 0x5740e013, 0x46ba8900, 0x23664c51, "....." },
  [95315] = { "Rivergladesの報告", "Captain Nials' CorrespondenceをRivergladesの南東の海岸沿いにあるFarholde KeepのDemar Brantに届ける。", "斥候の一人からの知らせによると、Wetlandsのはるか向こう、ずっとずっと南に、大勢の敵が集結しているらしい。\n\nさらに奇妙なのは、そこに同盟の開拓地があるらしいことだ。Farholde？その名には聞き覚えがある。\n\nこれを待つのはやめよう。手遅れになる前に話を始めるのが一番だ。ここでも手一杯なのだからな。\n\nこの書簡を持って行き、その部隊の指揮官を名乗る者に届けてくれ。", nil, nil, 0x1f867d7e, 0xa6c18e24, 0xa43e17f1, nil, nil, "...mm" },
  [95321] = { "Tazzikへの支払い", "TanarisのSteamwheedle PortでTazzikと対決する。", "Tazzikが賞金を受け取りにお前をよこしたって？冗談だろ？あいつのまぬけなチャンピオンは闘技場で2分ももたなかったんだぞ！あの負け犬は銅貨一枚も稼いじゃいない。\n\n俺の知ったことじゃないがな、相棒、俺ならさっさとSteamwheedle Portに戻るね。お前がここに突っ立って俺と話してる間にも、あのちっぽけなネズミのTazzikは、たぶん次の船に飛び乗ってここからずらかろうとしてるぜ。", nil, nil, 0x12009d0a, 0x04d46b31, 0x397dba38, nil, nil, "...mm" },
  [95322] = { "品物を手に入れろ", "Stranglethorn ValeのBooty Bayの外でBloodsail Trunkを見つける。", "最高のタイミングだよ、友よ。ちょうどBloodsail Buccaneersから積み荷を受け取りに行くところだったんだ。あいつらは俺のいい友達でね。Frizが金を払う気のあるものなら、何でも喜んで用意してくれる。\n\nでも、ゴホン、念のため、あんたに俺の連絡役になってもらっても損はないだろう。いい隊商人なら、ちょっと腕っぷしを見せつけても損はないって知ってるもんさ。もちろん、ただの抑止のためだよ。\n\nあいつら、保管のために町の外の丘にある箱に俺の荷物を置いといたって言ってた。ちょっと見てきてくれないか、な？", nil, nil, 0x8965a245, 0x62b03729, 0xc4d885aa, nil, nil, "...mm" },
  [95325] = { "泥棒にやられた！", "StranglethornのLake Nezferiti近くにあるVenture Co. CampでVenture Co. Ledgerを見つける。", "あの木箱にはもう大金を払ってるんだ。みすみすあいつらにくれてやるわけにはいかないぞ！\n\n積み荷が欲しいか？北のVenture Coの野営地に行って、この裏切りの張本人を突き止めてこい！もう金の問題じゃないんだ、{name}。これは正義の問題だ！それと、たぶん少しは金の問題でもある。", nil, nil, 0xe33ec9a8, 0x58fa8715, 0x15760d4d, nil, nil, "...mm" },
  [95326] = { "大いなる仕返し", "Venture Co. Agentを倒し、Booty BayにいるRuzzgotのためにRuzzgot's Shipmentを取り返す。", "<帳簿にはRuzzgotの配達の一つ一つが記録されている。最後の書き込みには、強奪は成功し、Ruzzgotの貴重品は近くにいるVenture Co.の手先が回収したと記されている。品物はまだその者が持っているに違いない。>", nil, nil, 0x9446396d, 0x1705fc92, 0xdd2746be, nil, nil, "...mm" },
  [95327] = { "終わり良ければすべて良し", "RivergladesのPowderfuse PortにいるFriz Frazzlesparkのところへ戻る。", "取引は取引ってことだな。Venture Co.は報いを受け、Frizはお宝を手に入れ、みんな幸せだ。我ながら、全体としてかなりスムーズな取引だったよ。\n\nさあ、とっとと行きな。もうすぐSouthsea Piratesから別の積み荷が届くんでね。", nil, nil, 0xa82e7590, 0x04ad02a4, 0x694d1d68, nil, nil, "...mm" },
  [95328] = { "Whispering Horror Residue", "Whispering Horror ResidueをUndercityのWar QuarterにいるFather Lankesterに届けてください。", "気は進まないものの、あなたは獣のうごめく残骸をこそげ取って集める。Undercityの誰かなら使い道があるかもしれない。", "何か私に渡すものがあるのか、{class}？", nil, 0xb283ff1d, 0xa13a9b4c, 0x1336682a, 0xcbd58f92, nil, "....m" },
  [95329] = { "現地にて", "Terral's Watchへ行き、Watcher Corneliusから状況報告を受ける。", "北の平原を見下ろす見張り塔がある。Hordeの軍勢の動きを追うための監視地点だ。\n\nそこに配置されている見張りはCorneliusという名だ。彼と話して状況報告を受けてきてくれ。あそこで一人きりなので、定期的に様子を確かめるようにしている。前もって言っておくが、彼は少々……無口だ。そもそもあれほど辺鄙な持ち場を任されたのも、それが理由だ。", nil, nil, 0xa2ea5c69, 0x73c32093, 0xf5a044e1, nil, nil, "...mm" },
  [95330] = { "汝の隣人を愛せよ", "Cassandraの余った農作物をTurner's Logging CampにいるHalligan Turnerに届ける。", "夫と私はここの北で農場をやっているの。収穫のたびにFarholdeへ来て、育てたものを売っているのよ。実りのいい年には、売れ残ったものを取っておいて、ちょっと元気が欲しい人たちにあげることにしているの。ご近所さんは大事にしなきゃね。\n\nうちの農場の北、川のすぐそばに伐採所があるわ。あそこの男衆も、食事に変化をつけるのに果物や野菜があればきっと助かると思うの。\n\nそっちへ行くなら、これをそこの現場監督に渡してくれないかしら？名前はHalligan Turnerよ。", nil, nil, 0xe903ac7d, 0xb9db9a6f, 0x2a1e469d, nil, nil, "...mm" },
  [95349] = { "Earthen Ring", "Zephras IsleからMulgore行きのスカイカッター船に乗り、到着したらAlaana Stormwalkerと話して下さい。", "カルトをめぐる最近の出来事でAzerothへ渡る予定が遅れ、しばらくはここValanaarに残らねばならない。代わりに、君と数人のWindshaperたちが我々の先遣隊となる。MulgoreではAlaana StormwalkerがWindshaperの到着を待っている。我々がここの用事を片付ける間、Azerothを探索してほしい。我々もすぐに合流する。\n\n準備ができたら、このロッジのすぐ外の桟橋へ行き、そこのskycutter船に乗ってくれ。\n\nBanu-Alah、{name}。", nil, "またZephrasから冒険者が来たか。何よりだ。風は間違いなく我々に味方している！ ここで落ち着くまでにはしばらく時間がかかるから、その間にこの新しい土地を見て回るといい。\n\nAzerothは胸躍る新世界だが、危険な世界でもある。この新たな冒険に備えて、近くの土地をよく知っておくといいだろう。", 0x28da0b16, 0x74e6dafa, 0x76858aa9, nil, 0xde8ad8f1, "...m." },
  [95350] = { "Azerothへようこそ", "Orgrimmarへ行き、Valley of WisdomにいるThrallと話してください。", "この下の世界は広い。そして我々の新しい盟友こそが、我々が生き残るための鍵だ。\n\nEarthen Ringは、志を同じくする民の誇り高き集まりである「Horde」の一員だ。近くのThunder Bluffの街もHordeの一部で、さらに東には首都Orgrimmarがある。\n\nThunder Bluffの中心にいるフライトマスターを訪ねるといい。Orgrimmarまで乗せていってくれる。そこでWindshapersの代表として、Hordeの大族長、Thrallと接触するのだ。風がお前を導かんことを、{name}。", nil, "Lok-tar、{class}。私はThrall、Hordeの大族長だ。\n\nEarthen Ringの使者から、Windshapersの者たちを迎えることになると聞いていたが、こうしてお前がいる。ここOrgrimmarでハイエルフが目の前に立つとは思いもしなかったが、それでもHordeはお前を客人として歓迎する。\n\nHordeの領地を旅することを認めよう。名誉と共に行け、Windshaper。", 0x2f003d6f, 0x53ee86b6, 0x7024f167, nil, 0x5185d5e8, "...m." },
  [95383] = { "発送と取り扱い", "Friz's Secret StashをSteamwheedle PortにいるTazzikに届ける。", "<Wharfmaster Steamfizzleはあなたが差し出した硬貨を調べている。>\n\nおっほう！あのFrizは新しい世代をしっかり育ててるねえ。お待たせしてすみませんね、お客さん。町の誰かに木箱を届けに来たんだろう？そんなことは何も知らないけど、もし知ってたら、波止場のTazzikに話しに行くだろうね。あいつはそういうことに興味があるみたいだから。\n\nでも、手早く頼むよ、いいね？みんなに妙な勘違いをされちゃ困るからさ。", nil, nil, 0x2df4f691, 0x1421c036, 0x1cb7078c, nil, nil, "...mm", nil, nil, 0xcd83683e, nil, nil },
  [95384] = { "Partial Mystical Notes", "不完全な巻物をBooty BayのDudd Fizzlescrollのところへ持って行ってください。", "<魔法の巻物に書かれた奇妙な記号に、あなたは戸惑う。記された言語は分からないが、中に特に不安定な力は感じられない。奇妙な魔法の収集家なら、この巻物に何か使い道を見いだすかもしれない。>", nil, nil, 0xec99fcec, 0xa76f397b, 0x819e84fc, nil, nil, "...mm" },
  [95385] = { "Torn Mystical Scroll", "一部しかない巻物をBooty BayにいるDudd Fizzlescrollのところへ持って行く。", "<巻物の切れ端からかすかな魔力が漂っている。見慣れない言語だが、危険なものではないと直感でわかる。たいていの者にはこの羊皮紙は役に立たないだろうが、使い道を見いだす変わった収集家がいるかもしれない。>", nil, nil, 0x9d05aeb5, 0xa76f397b, 0x1b7d2cfd, nil, nil, "...mm" },
  [95417] = { "紫色の奴ら", "Clubtoeのために、Sunnygladeの地下の洞窟で行方不明のogreを見つける。", "Clubtoe、仲間行くの見た。何人か戻らない。何人か紫になって戻る。それ変。紫のやつら、もう仲間みたいにしない。\n\nほかのやつらどこ行った？なんで戻らない？Clubtoe考える。\n\nお前、強く殴る。たぶんお前、洞窟で仲間探す？たぶんお前、紫になる。それも変。", nil, nil, 0x494d5db5, 0x07743954, 0xe7ce4f0b, nil, nil, "...mm" },
  [95418] = { "知らせを広める", "Choggの首をRog'marにいるTran'gulに届ける。", "オレ、Twilightやめた。Clubtoe、もう自由なogre。\n\nオレ、Clugfist探しに行く。あいつ、Clubtoe見た中で一番でっかいogre。あいつ、Twilight出ていった。仲間たくさん連れてった。次、Clubtoeの番。オレ、自由なogreの仲間なる。みんな丘に行く。Clubtoe、丘恋しい。もう岩割りしない。たぶんお前、いつか来る？\n\nオレ、安全になるまでここいる。お前、Chogg'Zacの頭、仲間のとこ持ってく。いや。たぶん頭1つ。オレも1つもらう。公平な取引。", nil, nil, 0x2e6074fc, 0xc63cec3c, 0xbd25ab1c, nil, nil, "...mm" },
  [95420] = { "巨人の地", "Choggの首を北にあるogreの街に届ける。", "明らかに、このはぐれogreどもはTwilight's Hammerの味方ではない。我らオークには、ogreとともに戦ってきた誉れある歴史がある。今こそ、あの古き盟約を再び呼び起こす時かもしれん。そして、この首がその鍵となるやもしれぬ。\n\nはるか北の丘でogreが動いているとの報告がある。このClubtoeの言うことが本当なら、そこがこの氏族の住処に違いない。奴らの砦へ行き、我らの友好の証としてこの戦利品を差し出せ。運が良ければ、お前を踏み潰す前に提案を聞いてくれるだろう。", nil, nil, 0x6c60d0c4, 0xfa36b640, 0xad996936, nil, nil, "...mm" },
  [95424] = { "力こそ正義", "Bolder'okにいるClugfistのために、Twilight Maulerを$N1体とTwilight Firecallerを$N2体倒す。", "ここのogre、力と血を重んじる。\n\n弱いやつら、Bolder'ok出ていく。Twilight's Hammerに戻る。\n\nお前、でかくない。たぶんお前、強い。Clugfistに力見せて、弱いogre叩き潰せ。ちっこい生き物にできるなら。", nil, nil, 0xcf499072, 0x5fff806e, 0x84414e3b, nil, nil, "...mm" },
  [95425] = { "資格なき王者", "Bolder'okにいるClugfistのために、KlunkからSkullthumperを手に入れる。", "Klunk、昔はClugfistの一番のチャンピオン。あいつ強い。オレ、Klunkにすごい武器やった。\n\nでもClugfist間違ってた。Klunk、ほかのやつらと同じで弱い。あいつ、Bolder'ok出ていった。Twilight's Hammerに戻った。ogre連れて、水の東の洞窟行った。すごい武器も持ってった！\n\nあれ、Clugfistの武器！Klunkの頭蓋骨叩き割って、Skullbasher取り返せ。あいつ、もう誰のチャンピオンでもない！", nil, nil, 0xdd6c393c, 0xc4de314c, 0xf6b8060f, nil, nil, "...mm" },
  [95426] = { "Rog'marの物資", "Rog'marの北の訓練キャンプからHorde Supply Shipmentを$N1個取り戻す。", "この地域への物資の輸送は容易なことではない。あらゆる方向を、あらゆる種類の悪党どもが取り囲んでいて、それぞれが自分の分け前を狙っている。\n\nさて、そうは言ったものの、これはRog'marの成長を鈍らせる好機かもしれない。我らがオークの友人たちの計画に、ちょっとした邪魔を入れてやるのはどうだ？\n\nRog'marの北にある奴らの訓練場へ向かい、補給物資を奪ってこい。立て直しにかかる時間だけでも、我が軍は戦える状態を保ち、一方の奴らは……まあ、言わずともわかるだろう。", nil, nil, 0x94aaff8f, 0x452706fa, 0x019dbe3c, nil, nil, "...mm" },
  [95427] = { "Twilightを終わらせろ！", "Clubtoeのために、Sunnygladeの洞窟でChogg'Zacを倒し、その首を集める。", "Clubtoeの仲間……死んだ？なんで？\n\nこれ、Chogg'Zacのせい！あいつら、ogre強くするって言った！あいつら、うそつき！！\n\nもう岩割りしない！ちっこい生き物、Clubtoe手伝って、かわりにChogg'zacのバカな頭叩き潰す！", nil, nil, 0xdfa3c368, 0x3d4e26c0, 0x7a41956b, nil, nil, "...mm" },
  [95428] = { "Clugfistの布告", "Rog'marにいるKrom'roshに報告する。", "ちっこい{race}、Twilightうまく叩き潰した。たぶんお前のHorde、Clugfistが思うより強い。\n\nお前、Bolder'okにいてもいい。今はな。\n\nほかのちびどもに伝えろ。もうすぐまた血を流すと。", nil, nil, 0x9805b458, 0x0c4f9d27, 0x296725a3, nil, nil, "...mm" },
  [95433] = { "処刑人に死を", "Bolder'okにいるClugfistのために、Twilight ShroudのExecutioner MorgからExecutioner's Maceを手に入れる。", "ClugfistがTwilight出ていくとき、1体のogreが道ふさいだ。Morg。\n\nMorg、でっかいogre。Clugfistとほとんど同じくらいでっかい。でも一番でっかくない。あいつ、自分守るのにちびども要る。Clugfist、一度も正々堂々戦えなかった。今度はオレたち、正々堂々戦わない。\n\nMorg探せ。ちびどもたくさん連れてこい。あいつ殺せ。maceをClugfistに持ってこい。そしたらTwilight、もうオレたちに挑まないってわかる！", nil, nil, 0x0019573e, 0x52aaa4fb, 0x8a4b297b, nil, nil, "...mm" },
  [95472] = { "残念賞", "Tazzik's Sweaty ShirtをPowderfuse PortにいるFriz Frazzlesparkのところへ持って行く。", "だから言ってるだろ、Frizに金を返せないんだって！残ってるのは着てるこのshirtだけなんだよ！\n\nなんでそんな目で俺を見てるんだ……", nil, nil, 0x60f5ce71, 0xa9ff54a5, 0x25c4a902, nil, nil, "...mm" },
  [95494] = { "傷ついた誇りとライオンの皮", "BarrensのSavannah MatriarchsとSavannah Patriarchsから、Savannah Lion Hidesを6枚集めてください。", "剣の腕が立って、時間に余裕のある者に、ライオンの皮集めを手伝ってほしい。見知らぬ者にこんな助けを頼むのは誇りが傷つくが、最近脚を怪我してしまってな。治るまでは自分で狩りに出られる状態じゃないが、果たさねばならん約束がある。\n\nこのあたりでは、大きな奴ほどたいてい皮が上等だ。まずはそいつらから始めてくれ。", "狩りの調子はどうだ？", "ああ、これならちょうどよさそうだ。私は地元の革なめし職人と取り決めをしていてね、この生皮を届ける代わりに、商売で使ういろいろな仕上がった革製品を受け取っているんだ。\n\n取り決めで私の側が不足したことは一度もない。怪我をしているからといって、今さらそうするつもりはないよ。", 0x5b2ff02d, 0xce49bfcd, 0x5cce729a, 0xe02b27bb, 0x29852b6b, "....." },
  [95495] = { "隠者の皮なめし職人", "Bundle of Hidesを、BarrensのDry Hillsを見下ろす尾根にいる隠者に届けてください。", "この皮は、よく取引している皮なめし職人に届けるものだ。そいつはちょっとした世捨て人で、俺の後ろの尾根の頂上にひとりで住んでいる。今の俺には急な斜面を登るのは楽じゃないから、代わりに届けてくれたら恩に着る。\n\nああ、それと、その皮なめし職人の……見た目のことだが。驚かなくていい。見た目はああだが、危険はない。これは本当だと誓う。", "ようこそ、{class}。今日は何の用で私の土地まで来たのかね？", "では、Vrangがあなたをよこしたのですね？よろしい。この皮を届けてくれて感謝します。Vrang自身が旅をしてこられなかったのは残念です。彼と話をしたい件があるのです。", 0xc91f6041, 0x2e6fcebc, 0xf3a9275e, 0xbe27a510, 0xd3180b55, "....." },
  [95507] = { "Vrangの獲物", "BarrensのSprung Trapsにある罠から、Trapped Gameを8つ集めてください。", "外に出ているついでに、俺の罠を見てきてくれるとすごく助かる。谷じゅうにばらまいてあるんだ。\n\nかかっている小さな獲物を持ってきてくれ。ただ、他の野生の動物には気をつけろよ。このあたりは、気を抜いていると危ないからな。", nil, nil, 0x56a6a9a8, 0xc7e5f7a1, 0xd203b57b, nil, nil, "...mm" },
  [95508] = { "招かれざる客", "Terry LongdrinkとKul Tirasの海兵隊との遭遇を、Waltonが生き延びられるよう手助けしてください。", "ああ、かつてはKul Tirasの海軍にいた。Lord AdmiralがTheramoreを奪ってDurotarでの作戦を始めた後、俺はそのやり方に……「異議」があってな。特に、民間人を処刑するやり方にだ。\n\n話にはまだ続きがあるんだが……待て……あれは何だ？\n\n男たちの一団が尾根を登ってくるぞ！", nil, "さて、どうやら皆生きているようだな。私は……いつかあれに追いつかれると分かっていた。今日ここで助けてもらった恩は忘れない。\n\nどうか、これを受け取ってくれ。大したものではないが、せめてもの礼だ。\n\n道中気をつけて、{class}。", 0xaedbb4a0, 0xfb874c5b, 0x5b6957f0, nil, 0xd4531345, "...m." },
  [95511] = { "初めての猫の友", "騎乗用のsaberを見て回り、最初の乗騎を選ぶ。", "ごきげんよう、友よ！今日はまさに大切な日ですね。今日、あなたは初めてのsaberと絆を結ぶのです。\n\nご存じかもしれませんが、saberは非常に賢く、絆を結んだ乗り手にこの上なく忠実です。これほど気高く揺るぎない相棒はほかにいないでしょう。ですから、あなたには大切な選択が待っています。あなたとsaberは共に世界を旅するのですから、よく考えて選んでください！心配はいりません。どれを選んでも、それが正しい選択なのです。\n\nさあ、saberたちを見てきて、選び終えたら私のところへ戻ってきてください。", nil, nil, 0x67e095c9, 0x60d306c0, 0x76ee9d49, nil, nil, "...mm" },
  [95534] = { "Strahnbradの謎", "Strahnbradの謎を解き、Hillsbradの町で調べた結果を報告する。", "<メモはところどころ焦げているが、まだ読める。>\n\n噂では、あの古いふいごは意志を持っていて、誰も見ていないときに勝手に動き出すらしい。怪談だろうが知ったことではない。私が戻る前に真相を突き止めておけ。\n\nStrahnbradには大きな力がある。私には分かる。\n\n< メモの残りは、炎の魔法で焼かれたかのように焦げて破れている。 >", nil, nil, 0x84d1d4cf, 0xe5975afe, 0x53e7de0b, nil, nil, "...mm" },
  [95561] = { "愛しのリンゴ", "Farholde KeepにいるTessa Dawnbrightのために、Fresh Appleを$N1個集める。", "<赤ん坊のDawnbrightの大きな泣き声がFarholde Keepに響き渡っている。Tessaは疲れた笑みを浮かべてあなたを見る。>\n\nあら、こんにちは、冒険者さん。うるさくてごめんなさいね。この子、Emmaったら今日はずいぶんぐずっていて、でもどうしてなのかわからないの。何か食べ物をあげれば落ち着くかもしれないわ。\n\nこの子が食べられるものを探すのを手伝ってもらえないかしら？夫が物資を取りに出かけていて、私は手がふさがっていて自分では取りに行けないの。このあたりでapplesをいくつか見つけてくれたら、この子においしいマッシュを作ってあげられるわ。", nil, nil, 0xae845ae0, 0x4c19a9ea, 0xdecef8a0, nil, nil, "...mm" },
  [95562] = { "首を落とせ", "Apprentice Claireのために、Sunnygladeの地下の洞窟でChogg'Zacを倒し、その首を取ってくる。", "打ち明けなければならないことがあります。確かにLady Amberhallは私にあの標本を集めるよう命じましたが、本当は私が自ら志願したのです。Sunnygladeはかつて私の故郷でしたが、戦争に奪われました。魔物がいまだにそこを汚していると知りながら、休むことなどできませんでした。Hordeであれ、Twilightであれ。\n\n奴らから学んで得られる勝利など、ここにはありません。学ぶことなど何もないのです。奴らは紛れもない獣です。獣のように始末されるべきです。\n\nこの洞窟の底にいる奴らの親玉を倒し、これを終わらせなければなりません。師もきっとわかってくださるでしょう。", nil, nil, 0xd07b970e, 0x6a3352c2, 0xdd4da7e5, nil, nil, "...mm" },
  [95601] = { "紫色の奴ら", "Empowered Bruteを$N1体とTwilight Ritualistを$N2体倒し、SunnygladeにいるClubtoeのところへ戻る。", "<この死んだogreは、Clubtoeが探していた仲間の1体に違いない。Twilight's Hammerは構成員に儀式を施し、一部の者を強化し、それ以上の者を殺しているようだ。\n\nこれらの儀式師と彼らが生み出した怪物どもは、広まる前に止めなければならない。>", nil, nil, 0x494d5db5, 0x0bfcb3ae, 0xda294067, nil, nil, "...mm" },
  [95602] = { "吐き気を催す光", "Sunnygladeの地下の洞窟の各所にあるTwilight Ritual Circleを$N1個破壊する。", "オレ、岩割り嫌い。一日じゅう割る。Chogg'Zacがそう言う。あいつ、でっかいボス。ちびども潰せって言う。でも今、オレたちちびどものために働く。それバカ。\n\nなんで岩割る？オレ知らない。岩の中にキラキラ光見つける。Chogg'Zac、キラキラ好き、たぶん。お前もキラキラ光のために来た？ほかのやつら、それ気に入らない。あいつら、光すごく好き。光で絵描く。\n\nClubtoe、わからない。光、Clubtoe気持ち悪くする。オレ、光嫌い。オレ、キラキラ絵ぶっ潰したい！でもChogg'Zac怒る。Clubtoe潰される。それ悪い。でも誰かやるべき。", nil, nil, 0xaf1ab0d2, 0xe30ca35a, 0xb631f163, nil, nil, "...mm" },
  [95603] = { "鐘楼のコウモリ", "Sister Rowlandのために、Farholde CathedralでRoosting Duskbatを5体倒す。", "Lowley修道士と私が、より世俗的な立場でFarholdeに仕えるようになってから、ここの教会は使われなくなってしまいました。戦いが終われば、この場所に光を取り戻せると思いたいのです。もっとも、それはずっと先のことになるのではないかと心配ですが……\n\nそれでも、その日が来ることを願って、教会を使える状態に保っておく必要があります。\n\nそのために、教会の上の階にコウモリの群れが住みついてしまいました。追い払っていただけると大変助かります。", nil, nil, 0xac70e617, 0xc749222c, 0x43852880, nil, nil, "...mm" },
  [95613] = { "光を絶やさずに", "Holy Candleを$N1本、Farholde KeepにいるSister Rowlandのところへ持って行く。", "もう教会で礼拝は行っていませんが、教会の地下墓所にある戦死者たちの墓に、ろうそくを灯し続けることは大切だと思っています。私にとって、ろうそくの炎を絶やさないことは、彼らが忘れられておらず、その犠牲が無駄ではなかったという証なのです。\n\nよろしければ、この儀式を続けられるよう、candlesを持ってきてください。私にとって大きな意味があります。\n\nどこで見つければよいかわからなければ、教会のすぐ外の家にいるMarlaと話してください。彼女は友人ですから、分けてもらえるかもしれません。", nil, nil, 0x53bbf370, 0x9a606ab7, 0xea1081ff, nil, nil, "...mm" },
  [95615] = { "追悼", "Farholde KeepにいるSister Rowlandのために、礼拝堂の墓地の墓にMemorial Candleを$N1本供える。", "よろしければ、この追悼のろうそくに火を灯す役目をお願いしたいのです。すぐ外の墓地へ行き、消えているろうそくを見つけたら、どこでも新しいろうそくを置いてください。\n\nこのような務めは、あなたのほかの冒険のような興奮とはほど遠いものでしょう。けれど、これを奉仕と内省の機会だと考えてください。私たちより先にこの世を去った人々に思いを向ける静かなひとときです。そうして私たちは歩み続け、この世界をより良い場所にしていけるのです。", nil, nil, 0x055586d2, 0xaef8d28f, 0x0cd602b9, nil, nil, "...mm" },
  [95621] = { "谷の異変", "壊されたキャラバンへ行き、Kul Tiransがなぜここにいるのかを探ってください。", "今朝、下の谷で何かを探している人間の一団を見つけた。ライフルのスコープでよく見てみたら、Kul Tirasの紋章をつけた兵士なのは明らかだった。\n\n俺からの仕事を引き受けてくれるなら、南の壊れた隊商のそばにある、そいつらの野営地へ行ってくれ。見つけた奴は殺して、なぜここにいるのか探ってくれ。", "いまだにDaelin Proudmooreの旗を掲げる艦隊の残党どもは、死ぬ前の提督本人と同じく腐りきった野蛮な連中だ。\n\nなぜTiragardeからこれほど離れた場所にいるのかは分からんが、良いことのはずがない。", "では、彼らは脱走兵を探しているのか……まあ、過去がついに私に追いついたらしい。", 0x389c29a3, 0xef54682f, 0xcaabc078, 0xdcde325c, 0x518baf21, "....." },
  [95642] = { "忌まわしき魔法", "Apprentice Claireのために、Sunnygladeの地下の洞窟にいるTwilight's Hammerの教団員とTwilight Ritual Circleから、Crystal Catalystにサンプルを$N1個吸収する。", "そこのあなた！来てくれてよかった、光に感謝します。Amberhallに言われて私を探しに来たのですか？\n\n違う？そんなことだろうと思いました。Ashe Amberhallは私をここへ送り、Twilight's Hammerを調べさせたのです。見てのとおり、奴らはRivergladesの中で何かを掘っています。でも、それが何かを突き止めるには、奴らの妖術の標本が必要なのです。\n\nFarholdeがその標本を手に入れることは何より重要です。お願いです、{class}。このcatalystを持っていってください。教団の力を吸い取るよう魔法がかけてあります。ルーンでも教団員でも構いません。ただ高く掲げれば、あとはこれがやってくれます。", nil, nil, 0xda2c4edb, 0xa3c91c9c, 0x35d2d396, nil, nil, "...mm" },
  [95643] = { "無差別の粛清", "Sunnygladeの地下の洞窟内で、Twilight Ritualistを$N1体とEmpowered Bruteを$N2体倒す。", "Lady Amberhallのもとで闇の術を学ぶ弟子として、見かけによらず、普段なら一人でたいていのことは片づけられるのです。ですが、洞窟いっぱいの虚無の力を注がれたogreは予想していませんでした。\n\n捕まらずにここまで下りてこられたのなら、あなたもきっと強いのでしょう。私は、あのogreどもとその主人たちがうろついている中で、そこまで運がよくありませんでした。世のためと思って、あの醜い獣どもを始末してください。目的を持った狂信者からは、力を得ていてもいなくても、ろくなものは生まれません。", nil, nil, 0x274a4d72, 0x9d6406b2, 0xfbebad5b, nil, nil, "...mm" },
  [95646] = { "Highlandの恐怖", "Excavation Sitesの中でHighland Horrorを倒し、その根の核をWetlandsのRethiel the Greenwardenのところへ持って行って下さい。", "この汽水の湿地には、南からの塩気のない水がより多く湛えられている。心が痛むが、我が根の内に、あの山の峡谷を伝って染み出す穢れを感じるのだ。\n\nこの地の生き物たちは、我らの低地の者たちと同じく、穢れにより激しく反応する。生命の夜明けより海の硬き塩を知らぬゆえ、かような邪悪に抗う力がほとんどないのだ。\n\nあの高地へ行き、Highland Horrorの根の核を我が元へ持ってくるのだ。", nil, nil, 0x79650957, 0x81ee8465, 0xbce12a7e, nil, nil, "...mm" },
  [95647] = { "茂みに消えたもの", "Excavation SitesでArdin Grassmanを見つけて下さい。", "夫のArdinには、自然を感じ取る稀な才能があるの。私の錬金術に必要な薬草や花を摘むためなら、どんな峰にも登って、うちの棚と食料庫をいっぱいにしてくれるわ。\n\nでも、何か厄介事に巻き込まれたんじゃないかと心配なの。発掘隊が物資を求めてここを通ったのよ。彼らはいろいろな話の中で、見たこともないほど高くそびえる草のことを話していたわ。夫は、それを自分の目で確かめに行かなくちゃって言っていたの。もう帰りが遅すぎるわ！\n\n彼について何か分かったら、ありがたいわ。", nil, nil, 0xc3371e69, 0x4d0fc432, 0x6d7c1497, nil, nil, "...mm" },
  [95663] = { "Dragonmawの噂", "Wetlandsへ行き、Dragonmawの野営地の上にある丘でDeathstalker Agentに会って下さい。", "Dragonmawは手ごわい氏族だ。\n\n奴らはドラゴンをも従わせるほど強力な束縛の魔法で知られている。噂では、Wetlandsでその力を見せつける準備をしているらしい。真実かはったりかはともかく、Deathstalkersは半端なささやきでは動けん。壊れた符号から私に伝わったのは、そこまでだ。\n\nDragonmawの野営地を見下ろす丘で、deathstalkerの工作員が手を必要としている。そこで彼女と落ち合え。次の手はずは彼女が明かしてくれる。", nil, nil, 0xecfb9de3, 0x607aac05, 0x19f544b5, nil, nil, "...mm" },
  [95664] = { "長老の知識", "Titan RelicをThunder BluffのElder Riseへ持って行き、それについて詳しく教えてくれる人を探して下さい。", "この珍しい複合物の欠片は、生きたプリズムのように光を散らす。その性質は定かではないが、その力は古のものに感じられる。この過ぎ去った時代の遺物に最も詳しい者たちは、Thunder BluffのElder riseにいるに違いない。", nil, nil, 0x1d764e46, 0x4a860375, 0xd36a8f92, nil, nil, "...mm" },
  [95682] = { "大口を開く", "Excavation Site内のDragonmawの軍勢を倒し、回収した物を持って外にいるDeathstalker Agentのところへ戻って下さい。", "Dragonmawね。<彼女は乾いた、面白がるような嘲笑を漏らす。>\n\nあのドラゴン使いの氏族の残党は、かつての力を取り戻すきっかけになるものを見つけたと思い込んでいる。誰の目から見ての話かしら……あの偽りの大族長？\n\nExcavation Sitesにいるあの寄せ集めの氏族を一掃して、我々のDeathstalkersが気づかれずに入り込めるようにしなさい。\n\nDragonmawが何か目ぼしいものを身につけていたら、私のところへ持ち帰りなさい。この情報は、我々と王家の司令部の間だけに留めておかねばならないの。", nil, nil, 0x01716485, 0x9fb46d83, 0x5cd87c72, nil, nil, "...mm" },
  [95697] = { "変わる好み", "WetlandsのExcavation Sitesに入り、Thicket Raptor Meatを持ち帰って下さい。", "Zamjaが言うには、家庭料理がもっと必要らしい。\nraptorを売り始めれば、普段Borstan's Firepitに来ない客も呼び込めると考えているんだ。\n\n彼女の考えも悪くない。だが俺は、俺たちの生まれた村の匂いを超えるものが欲しい。ここはOrgrimmarだぞ！ Borstanは、皆が慣れ親しんだ好物を壮大に仕立てたものを出すべきだ。\n\n最近、あるハンターがWetlandsから戻ってきた。Excavation Sitesのthicket raptorsの巨大な鉤爪を持ってな。\n\n仕事を引き受けるか？", nil, nil, 0xefd7f8a7, 0x406ca9c2, 0xc77dbee9, nil, nil, "...mm" },
  [95737] = { "Caitlinを探して", "Menethil HarborのCaitlin Grassmanと話して下さい。", "時々、私は同業の者たち、つまり珍しい植物や土地の奇妙なものを研究する薬草学者や変わり者たちと手紙をやり取りしています。発見を交換し合い、ときにはこの先に待つものについての警告も交わすのです。\n\nWetlandsのある錬金術師が、夫の加わっている発掘隊のことを書いてきました。長く失われていた原初の草の痕跡を見つけたというのです……でも、それがどれほどあって、どれほど手に入れやすいのかは、知らせてきませんでした。\n\nもしできるなら、Menethil HarborのCaitlin Grassmanの様子を見てきてください。", nil, nil, 0xf6e09b80, 0x29283070, 0xb0744041, nil, nil, "...mm" },
  [95748] = { "Gurubashiの古き伝説", "皮と木炭を使って、Third Troll Legendの石板の拓本を取る。", "これは妙だ。あなたが持ってきてくれた石板のこの部分は、失われた都市I'lalaiを、まるで広大に広がる巨大な文明であるかのように語っている。だが、岩礁の沖にある遺跡は、それほどの規模のものにしては小さすぎる。\n\n{name}、Vile Reefの北の海岸沿いの丘に、古いトロールの遺跡がある。その中に、失われたトロールの都市の伝説が刻まれた石板があるのだ。この伝説をさらに調べたい。\n\nこの皮と木炭を持っていって、その石板の拓本を取り、私のところへ戻ってきてくれ。", nil, nil, 0x1163f14b, 0x8eb3fa59, 0x85f90475, nil, nil, "...mm" },
  [95770] = { "失われた都市を探して", "Vile Reefを探索し、洞窟の入口を見つける。", "伝説を読み返したところ、失われた都市の場所を間違えているわけではなさそうだ。だが、まだ見落とされている細部があるのかもしれない。\n\n若い頃、私はVile Reefの遺跡によく潜っていたものだが、それはmurlocがそこに住み着く前のことだ。記憶が確かなら、そこには洞窟があった。\n\n今その辺りにnagaが集まっていると聞いた。珍しいことだ。何が奴らをそこへおびき寄せたのか知りたい。\n\nVile Reefのすぐ西を探索して、何か分かったら私のところへ戻ってきてくれ。", nil, nil, 0xbfc53c6c, 0x5befc8cb, 0xba46d29c, nil, nil, "...mm" },
  [95771] = { "闇の味", nil, nil, nil, nil, 0x8583a882, nil, nil, nil, nil, ".mmmm" },
  [95772] = { "Songbladeの捜索", "Whelgar's Excavation Siteで、Dorin Songbladeの兄弟Daewynを探して下さい。", "兄貴の奴、Loch Modanから来た発掘屋の連中と一緒に、俺をWetlandsへ引っ張っていこうとしたんだ。ドワーフが一人も足を踏み入れたことのない丘へ、何かの発掘に向かうって言ってたな。\n\nああ、行ってたさ。この山ほどのベルトの直しが遅れてなきゃな。\n\nだがDaewynは普段、出発した後に手紙をよこすんだ。今回は何の音沙汰もねえ。妙な胸騒ぎがするんだよ。\n\nそっちへ行くなら、兄貴の様子を見てきてくれねえか？", nil, nil, 0x4225ee40, 0x72145fde, 0x91fbce45, nil, nil, "...mm" },
  [95773] = { "水中の敵", "Brinescale SkirmishersからBrinescale Tridentsを$N1本集める。", "{class}、ちょうどいいところに来たな。我々の海岸のすぐ沖でnagaが活動しているという新しい報告を受けたばかりだ。奴らは海底近くの古いトロールの遺跡の周りに群がっているらしい。\n\n我々は地元のBloodscalpや、隊商を荒らすogreからの防衛ですでに手一杯だ。海からの奇襲を受ける余裕はない。\n\n行って、できるだけ多く倒し、成果の証として奴らの三叉槍を持ってきてくれ。", nil, nil, 0xf6a51353, 0x23c1e22b, 0xbd430784, nil, nil, "...mm" },
  [95774] = { "彼女の名はOlgra", "quilboarを倒し、Mankrikの弔いのためにOlgra's Adornmentsを$N1個集めてください。", "私を救ってくれた治療師も、彼女を救うことはできなかった。彼女は戦いの中で死んだのだ。名はOlgra。私は決して彼女を忘れない。\n\n彼女の遺体に飾りはなかったのか？ 磨いた骨の宝飾をたくさん身につけていたのだが。\n\n彼女が倒れたあたりにいるRazormane Raidersを倒し、彼女の大切な作品を見つけてきてくれ！\n\n彼女を偲んで私が建てる記念碑に、それを添えるつもりだ。", "今の私には思い出しかない。だが、それが色あせることのないよう、Olgraをたたえる記念碑を建てるつもりだ。", "この装飾品は妻の慰霊碑に供えよう。彼女を決して忘れないように。我が血は永遠に復讐に燃え続ける！\n\nお前は私に……いや、我々に……大きな恩を施してくれた、{name}。", 0xe0733c23, 0x64b2ed87, 0x1085cf6b, 0xcb32b1fe, 0x22fd675b, "....." },
  [95775] = { "Drowned City", "皮と木炭を使って、Drowned Cityで見つかる石板の拓本を取る。", "これから頼むことは決して容易なことではないぞ、{class}。成し遂げるには、おそらく強い仲間が必要だろう。\n\nnagaが守っている洞窟の向こう側にある遺跡について、もっと知りたい。私の推測が正しければ、それはまさしく失われた都市I'lalaiかもしれない。手に入る失われた歴史の知識の量は比類ないものになるだろうが、私は年を取りすぎて自分では行けない。\n\n遺跡に入り、そこで見つけた石板の拓本を取って、私のところへ戻ってきてくれ。", nil, nil, 0x7b66254a, 0xda9d19e9, 0xf184a1b6, nil, nil, "...mm" },
  [95776] = { "良いBrinescaleとは……", "Drowned CityでVar'Takaを倒す。", "我々の海岸のすぐ沖でnagaを倒してくれたのは見事だった。だが、奴らがこれほどの数で我々の海域にいるということは、さらに大きな脅威があるということだ。\n\nKin'weelayと話したところ、彼はこのBrinescaleのnagaがDrowned Cityの遺跡に入り込んでいると考えている。nagaがそこにいるなら、何か良からぬことを企んでいて、おそらく何かを探しているのだろう。\n\nここの我々を危うくするようなものを奴らの手に渡すわけにはいかない。これに終止符を打つ時だ。奴らの指導者を倒し、私のところへ戻ってきてくれ。", nil, nil, 0x6893b9a2, 0x0ab0d353, 0xee8da360, nil, nil, "...mm" },
  [95786] = { "Southshoreの知人", "SouthshoreでLoremaster Dibbsを見つけ、Savage Coast Report Bundleを渡す。", "{name}、Hillsbrad Foothillsに、トロールの伝説と邪悪な魔法を研究している友人がいる。この忌まわしい魔法がどのようにColenel Kurzenの心をとらえたのか、彼なら何か見抜けるかもしれない。\n\nそれに、斥候の報告によると、地元のトロールたちがいきり立っていて、ある言葉を口にしているそうだ……「I'lalai」と。\n\nこれがKurzenの堕落と関係しているのか、知らねばならん！さあ、この呪物と伝説を、この偵察報告と一緒にLoremaster Dibbsのところへ持っていってくれ。運がよければ、彼がその秘密のいくつかを解き明かしてくれるだろう。", nil, nil, 0x519d5781, 0x96558c64, 0x8f76ce25, nil, nil, "...mm" },
  [95787] = { "水で2錠", "皮と木炭を使って、Drowned Cityで見つかる石板の拓本を取ってください。", "<偵察報告とトロールの伝説を読むLoremaster Dibbsの手が震えている。>\r\n\nまさか？この報告によれば、失われたトロールの都I'lalaiが、Stranglethornの沖合に浮上したようです！すぐに調査しなければなりません。いやはや、私の研究が正しければ、これは今世紀の考古学的大発見かもしれませんよ！\r\n\nどうか、Stranglethornまで戻るのは長い道のりだと分かっていますが、もしそのDrowned Cityに行くことがあれば、そこで見つけた伝説を集めて私のところへ持ち帰ってください。", nil, nil, 0x8a52ce4a, 0xda9d19e9, 0xfa014234, nil, nil, "...mm" },
  [95788] = { "Drowned Cityの魔術", "Drowned CityのトロールからI'lalai Fetishを$N1個集めてください。", "Brother Nimetzがあなたに持たせたSkullsplitterの呪物は確かに強力です。ですが、それがKurzenの容態の原因になったとは思いません。少なくとも直接には。\r\n\nそれでも、噂が本当で、失われたトロールの都I'lalaiが本当に水の墓場から浮上したのなら、呪われた都を浮上させるのに使われた闇の魔術が関係しているかもしれません。\r\n\nもしDrowned City of I'lalaiに足を踏み入れる勇気があるなら、見つけたトロールの呪物を集めて、さらなる研究のためにここの私のところへ持ってきてください。", nil, nil, 0xe9ed0635, 0xd05a8a60, 0xcb7fb810, nil, nil, "...mm" },
  [95789] = { "怪しいSaltseers", "Drowned CityのSaltseerの海賊からVoodoo Infused Artifactを$N1個集める。", "よう相棒、あんた、腕っぷしには自信がありそうだな。\n\nBaron Revilgazに言われて、魔法の品の噂に耳を澄ませてるんだ。噂じゃ、沈んでたトロールの遺跡が不思議なことに、その、浮かび上がったらしい。つまり、持ち主のいないお宝がたくさんあるってことさ。言いたいこと、わかるだろ？\n\n問題は、海賊どもも目をつけてるってことだ！それもただの海賊じゃない。Saltseersは特に魔法の遺物を集めてるんだ。Drowned Cityに乗り込んで、奴らを一掃して、盗まれた遺物を奪ってきてくれ。", nil, nil, 0xddbc09c1, 0xf479884c, 0x3fab9ac8, nil, nil, "...mm" },
  [95791] = { "Saltseerの船長", "Drowned CityでSaltseer Coronerを3体とCaptain Dreadriseを倒す。", "最近、Saltseerの海賊どもは目の上のたんこぶでね、しかもDrowned Cityにいると知って、なおさら厄介になった！いや、あいつらはいつだって厄介者なんだが、特に消えてほしい船長が1人いるんだ。あの忌々しいCaptain Dreadriseだ！\n\nあいつとその手下どもは、俺が狙ってる魔法の遺物を集めるのがやたらとうまくてな、張り合うのにはもううんざりなんだ。\n\nCaptain DreadriseとそのSaltseer Coronersを消してくれ。永久にな。", nil, nil, 0xe6ca7f0e, 0x94a2411c, 0x1f831f71, nil, nil, "...mm" },
  [95792] = { "奴らを一掃しろ", "Gelinda Coppergleamのために、Cinderscale Whelpを$N1体とCinderscale Warriorを$N2体倒す。", "大もうけしたいなら、ほかの連中が尻込みするところへ行かなきゃ！後ろのこの洞窟には、手つかずの鉱床がたっぷり眠ってるんだ。作業員を送り込めれば、とんでもない大金になるよ。\n\nただ、ちょっとした……ほんのちっちゃな……ドラゴンの問題があるだけさ。ほんと、たいしたことないって。\n\n中に入ってドラゴンを片づける手間を省いてくれるなら、たっぷり報酬を出すよ。おまけに、未来の鉱山王に気に入ってもらえるしね！", nil, nil, 0x12e349a6, 0xcb97e782, 0x58264e6b, nil, nil, "...mm" },
  [95795] = { "沼地に倒れた者", "Dorin Songbladeのところへ戻って下さい。", "<あなたはドワーフの亡骸を、彼のマントで覆った。>\n\nLakeshireへ向かい、Dorin Songbladeに、彼の兄弟がExcavation Sitesでどうなったのかを自ら伝えよう。", nil, nil, 0xbfc85885, 0x2739cdb1, 0x9e5ae38b, nil, nil, "...mm" },
  [95798] = { "魔法の網", "I'lalai FetishをDalaranにいるAbra Cadabraのところへ持って行く。", "{name}、このI'lalai FetishをDalaranにいる友人のAbraに届けてほしい。時間があれば、ぜひ彼女に調べてもらいたいのだ。\n\n彼女はトロールの風習や魔法にも特に関心があるので、この発見を解き明かすのはきっと胸躍ることだろう。\n\nただし、くれぐれも気をつけてくれ。Kirin Torは、自分たちの壮麗な都に誰を入れるかについて、少々うるさいことがある。まだ名高い訪問者になっていないのなら、彼らに気に入られる方法を見つける必要があるかもしれない。", nil, nil, 0x71ee526c, 0xc2dcabde, 0x4e9e940b, nil, nil, "...mm" },
  [95799] = { "Explorer's Leagueへの調査結果", "Loremaster Dibbs' I'lalai TranslationsをIronforgeにいるHistorian Karnikのところへ持って行く。", "すぐにIronforgeのExplorer's Leagueにいる同僚へ手紙を書かねば。これは歴史的な規模の発見だ。\n\nその手紙をIronforgeまで届けてもらえないだろうか？君のために、石板の私の翻訳の写しを書いておこう。", nil, nil, 0x1711b4d8, 0x6a18ec59, 0x10b2059b, nil, nil, "...mm" },
  [95803] = { "誠意の証", "Rudolph Gelhardtの首をUndercityのSylvanas Windrunnerに届けてください。", "汚れた司令官の首を取った今、それをUndercityへ届けてもらいたい。Sylvanas Windrunnerは我々をひどく疑っていて、ほとんどあからさまに見下している。\n\nRudolph Gelhardtの首をDark Ladyに届けろ。我々が自分たちの家の始末は自分でつけ、Forsakenの繁栄に身を捧げていることを示すのだ。", "なぜ私に話しかける、{class}？", "お前たちの種族のためにForsakenの中に居場所を勝ち取りたいというDanithaの誠意と願いは疑っていない。だが、お前の兄弟姉妹の誰かが狂い、光を自らの同胞に向けるのを目にするのは、これが最後ではないだろう。\n\nお前たちの忌まわしい教団を容認することが、もはやForsakenの利益にならないと判断する時が来るかもしれない。せいぜい民に忠実に仕え続けることだ。\n\n我々は見ているぞ。", 0x8a963535, 0x09f1d511, 0x27427458, 0x2d8b7e5f, 0x2b29670e, "....." },
  [95805] = { "An'sheとMu'shaの恩寵", "香が10分で燃え尽きる前に、Smoldering Incenseを南東の丘にあるAn'sheとMu'shaの祠へ運んでください！", "太陽と月、An'sheとMu'shaは、精霊のようにこの世界の一部ではありません。けれどもその光は、私たちに命と導きと希望を与えてくれます。\n\n私たちは世界の精霊に敬意を払います。ですから、双子にも敬意を払うのです。\n\nあなたも敬意を示したいのなら、このくすぶるお香を持って、南東の丘にある祠へ届けてください。台地を見下ろす、quilboarの南にある祠です。お香が燃え尽きる前に祠にたどり着けるよう、急いでください。\n\n濡らしてはいけませんよ！", "<香の煙が空へと立ち昇っている。>", "<香を火の中に空けると、その香りがあたりに漂い、あなたの手には空になった袋と、かすかな達成感だけが残った。>", 0x1483f5df, 0x82228fe2, 0x52a83811, 0xd4bc4ea6, 0xd28f1b93, "....." },
  [95809] = { "Heartwoven", "Menethil HarborのCaitlin Grassmanのところへ戻って下さい。", "自分で道を見つけて出ていく前に、少し休ませてくれ。\n\n<彼は荷物から葦を何本か取り出し、手早く編んで曲げ、ハートの形にする。>\n\nこれを持って、Caitlinに届けてくれ。もうすぐ帰ると伝えてほしい！ 君のおかげで道が開けたから、俺は自分の束をまとめて君の後を追うよ。\n\nありがとう。", nil, nil, 0x7c49eff3, 0xb6ab7769, 0x84c0de8c, nil, nil, "...mm" },
  [95810] = { "失われた遺物の運搬", "Titan RelicをWetlandsの発掘現場にいるProspector Whelgarのところへ持って行って下さい。", "あなたは岩の機械仕掛けの自動人形の、砕けた破片を拾い上げる。これまで触れたどんなものとも違う手触りで、正体不明の複合素材でできている。これは間違いなく「残骸」というより「装置」だろう。\n\nProspector Whelgarなら、自分の発掘現場でこの遺物について役に立つ話をしてくれるかもしれない。", nil, nil, 0x66a19050, 0x25ed1b64, 0x09d52652, nil, nil, "...mm" },
  [95816] = { "参加させてくれ！", "記入済みの書類をRedridge MountainsのElaine Comptonに届けてください。", "熟練の職人の皆さま、ごきげんよう！\n\nこの用紙にご記入いただくと、Azeroth全土であなたの生産スキルの広告看板を掲げる、非独占的・取消可能・法的に限定された許可が得られます！\n\nご記入後は、手続き開始のため、お近くのAzeroth Commerce Authority支部のContract Coordinatorまでお持ちください。\n\n楽しい物作りを！", nil, nil, 0xe71188a6, 0xaef04737, 0x5eb40123, nil, nil, "...mm" },
  [95817] = { "Rotgath Stonebeard", "IronforgeのGreat Forgeの近くにいるRotgath Stonebeardに会って下さい。", "Rotgath Stonebeardに会ったことはあるかい？Ironforgeにいるドワーフの鍛冶屋だ。おしゃべりな男じゃないが、いつも頼りになる。単純な作りの品を大量に作ってほしい時は、よく彼に頼むんだ。Stondryが自分で引き受けるには誇りが許さないような仕事さ。\n\n仕上がりの早さは抜群で、特に新しい職人が店を構える手助けとなると見事なものだ。看板を急いで作ってもらうなら、彼以外には任せられない。もし手こずらせるようなら、私の紹介だと伝えてくれ！", nil, nil, 0xcc87f187, 0x29aa8c0c, 0x265b4cd5, nil, nil, "...mm" },
  [95818] = { "急ぎの製作", "頼まれた材料を、IronforgeのGreat Forgeの近くにいるRotgath Stonebeardのところへ持って行って下さい。", "材料さえ揃ってりゃ、あっという間に片付けて送り出してやれるぞ！Mithril Barsが$N1本とHeavy Leatherが$N2枚要る。普段は他の金属なんかも要るんだが、場所を取ってた端材があるから、余分な部分はそれで間に合わせられる。\n\nああ、それとわしの個人的な頼みで、Goldthornも$N3本頼むぞ。女房がうまい茶の作り方を知っててな、驚かせてやりたいんだ。これがお前さんの支払いってことにしてくれ！", nil, nil, 0xae19085c, 0x93f08152, 0x8ce5bacd, nil, nil, "...mm" },
  [95819] = { "参加させてくれ！", "記入済みの書類をThe BarrensのJornahに届けてください。", "熟練の職人の皆さま、ごきげんよう！\n\nこの用紙にご記入いただくと、Azeroth全土であなたの生産スキルの広告看板を掲げる、非独占的・取消可能・法的に限定された許可が得られます！\n\nご記入後は、手続き開始のため、お近くのDurotar Supply & LogisticsのContract Coordinatorまでお持ちください。\n\n楽しい物作りを！", nil, nil, 0xe71188a6, 0x73fcb0bd, 0xb6355654, nil, nil, "...mm" },
  [95882] = { "お尋ね者：Scoutmaster Vargas", "Scoutmaster's EyeをRog'marにいるNeza Bloodsnoutのところへ持って行く。", "Rog'marの北東にある小島で、Allianceの偵察隊が目撃された。率いているのは斥候長で、そいつのせいで敵の動きを追うのがますます難しくなっている。あの野郎は、あからさまな嘲りとして、自分の汚らしいペットに俺の名までつけやがった。俺に狙われていることもわかっている。\n\nこの人間はあちこちに目を光らせている。その目を潰してやらねばならん。逃げられる前に片方はもう奪ってやった。斥候長がもういない証拠に、もう片方を持ってこい。自分が思っているほど手出しできない存在ではないと思い知らせてやれ。\n\n-- Neza Bloodsnout", nil, nil, 0x14a2c256, 0x49cfe0ef, 0xdd3ba7f1, nil, nil, "...mm" },
  [95883] = { "Tortured Soul", "Silverpine ForestのBeren's Perilにいる近くのアンデッドから、Tortured Soulを一つ手に入れてください。", "<急ごしらえの儀式の支度が、無造作に祭壇の上に集められている。書き付けの切れ端によれば、すべて揃っているようだ。足りないのは血の捧げ物と、Tortured Soulだけだ。\n\n周りのアンデッドは十分に苦しんでいるように見える。探しているものを持っているかもしれない。>", "<供物の石は不気味なほど静まり返っている。>", "<責め苦を受けた魂は、捧げ物の石の前で穢れた力を放つ。\n\nどうやら儀式の完成に近づいているようだ。>", 0xb60b70e3, 0x0d080853, 0x972297ea, 0x03dfcb1a, 0x2d800f13, "....." },
  [95884] = { "捧げ物の石", "Silverpine ForestのBeren's PerilでOffering Stoneを見つけてください。", "<書き付けの切れ端はほとんど判読できない。だが、まだ読める部分には、捧げ物の支度についての覚え書きがある。\n\n捧げ物の石と、儀式のことが書かれている。\n\nこの捧げ物の石は、近くで見つかるかもしれない。>", nil, "<石のざらついた表面には、奇妙な道具や品々が散らばっている。\n\nこれこそメモに書かれていた捧げ物の石に違いない。>", 0xa6de587b, 0x975b0b28, 0x838aeea9, nil, 0xaa91f891, "...m." },
  [95885] = { "血の捧げ物", "Tortured Soulを使い、Beren's PerilのOffering Stoneで血の捧げ物をしてください。", "<残るは血の捧げ物だけだ。\n\n書き付けの切れ端には「自ら望む生贄」とあった。\n\n強い恐怖が押し寄せてくる。>", "<供物の石は不気味なほど静まり返っている。>", "<捧げ物の石は今や沈黙している。どうやら儀式がその力を吸い尽くしたようだ。何のためだったのかは分からないが、もう終わったのだ。\n\nざらついた石はひび割れて崩れ落ち、もはや何の役目も持たない。\n\n残骸の中で何かがきらめいている……>", 0x3785a093, 0x7d15beec, 0xb34b8754, 0x03dfcb1a, 0x73aa5f70, "....." },
  [95912] = { "お尋ね者：Blademaster Kaijo", "Blademaster's BannerをFarholde KeepにいるEmber Bladewhisperのところへ持って行く。", "オークを一人斬り倒すたびに、別の者がその穴を埋める。しかもどういうわけか、前の者よりさらに手強い。腕利きのウォリアーがこの新しい世代を鍛えているに違いない。奴らの数を減らすつもりなら、損失を取り戻す機会を与えないようにしなければならない。\n\n勇敢な兵士がいるなら、このブレードマスターを見つけ出し、始末することが何より重要だ。おそらく今もHordeの前哨地の北にある訓練生の野営地にいるだろう。奴を倒し、bannerを奪い、オークどもの士気を打ち砕け。\n\n-- Ember Bladewhisper", nil, nil, 0xcaa9a163, 0x66f86f32, 0x5fdbd226, nil, nil, "...mm" },
  [95913] = { "王女にふさわしい", "Farholde KeepにいるTessa Dawnbrightのために、Coyote Peltを$N1枚集める。", "<Tessaは赤ん坊を揺らし、寝かしつけようとしている。>\n\nお腹が空いていないなら、ただ眠いだけなのかもしれないわ。正直に言うと、このEmmaはうれしい驚きだったけど、そのぶん少し準備が足りていなかったの。夫がこのすてきな揺りかごを作ってくれたけど、毛布が古すぎるんじゃないかと心配で。だって、この子には最高のものがふさわしいもの。\n\nまだ手伝ってくれる気があるなら、この子の寝床に敷くpeltsを見つけてきてもらえたら、ずっと感謝するわ。これで泣きやんでくれたら、Farholdeのみんなも感謝すると思うの。", nil, nil, 0x3787da47, 0x126c5316, 0xf43a5774, nil, nil, "...mm" },
  [95934] = { "利益の証", "Gelinda Coppergleamのために、Cubic Draconiaの欠片を見つける。", "私の測量道具が、この洞窟に前代未聞の鉱物の兆候を示してるの。Cubic draconiaって呼んでるわ。たぶん一財産になるわね。\n\nわくわくする話だけど、実在する証拠を見せられなきゃ、掘り出すのを手伝いに来てくれる人なんて誰もいないわ。もちろん道具の測定値はあるけど、みんな図表を眺めるより、大きくてキラキラした結晶を手に持ちたいものなのよ。\n\n中には土から突き出てる結晶がいくつかあるはず。ドラゴンを何匹かかわして1つ取ってきてくれたら、本当に助かるわ。", nil, nil, 0x40c81f11, 0x0e60bf69, 0xc68aae30, nil, nil, "...mm" },
  [95936] = { "竜殺しを称えよ", "Head of ScaldaronをRog'marにいるKrom'roshのところへ持って行く。", "ドラゴンの首は牙と鱗と灰ばかりだ。おぞましい生き物から奪った、おぞましい戦利品。手に持つと、最後に吐いた炎の息の熱が、いまだに口から放たれているのを感じる。\n\nScaldaronがもたらしていた脅威はもうないが、ここで起きたことはRog'marのウォリアーたちに知らせるべきだろう。", nil, nil, 0xfa82d67b, 0x675d23ae, 0xc4b52099, nil, nil, "...mm" },
  [95943] = { "現場監督の窮地", "Foreman's Crateを見つけ、Farholde KeepにいるBertrand Ironbrowのところへ持ち帰る。", "よう、若いの。わしの名はBertrand、Bertrand Ironbrowだ！よろしく頼むぞ。\n\n<Bertrandは汚れた手を差し出す。>\n\nここの立派な連中に、この砦の建設を監督するよう雇われてな。経験は足りんが、そのぶん気合いで補っとる！問題は、わしが道具をなくしちまったことだ。\n\nここの北西にある小さな木立で、Twilightの連中と少々やり合ってな。命を取るか道具を取るか、選ばにゃならんかった。一方では、わしは生きとる。もう一方は……まあ、わかるだろう。\n\n道具を探すのを手伝ってくれんか？", nil, nil, 0xd5e9d9a6, 0x3a069aaa, 0x8c54f8b0, nil, nil, "...mm", nil, nil, 0x84fbc76c, nil, nil },
  [95951] = { "拾って削って", "Turner's Logging CampのPeasant WoodpileからWood Bundleを集め、削ってMakeshift Stickin' Spearを$N1本作る。", "よう、ボス、Tan'janiの助けが要るのか？心配すんな、ちゃんと面倒見てやるさ。\n\nオークは斧で人間をぶん殴るのが得意だが、相手が気づく前に突き刺したいときは、ヘッドハンターの出番よ。お前も突き刺し方を覚えたいか？目を見りゃわかるぜ、へへっ。\n\nまずはお前自身のspearsを手に入れる。こいつは俺のだ。西の人間の野営地へ行って、奴らのwoodを奪ってこい。ナイフも持ってけ。奴らの材木を削って、突き刺すのにいいspearsにできる。それから持って帰ってこい。", nil, nil, 0x4fc22b5d, 0x57766d88, 0x551f1aa2, nil, nil, "...mm", nil, nil, 0xa19e88f8, nil, nil },
  [95957] = { "飲み干せ！", "Zizplink's Frothing MugをPowderfuse PortにいるGray Dawnbrightに届ける。", "ほらよ、チャンプ。あそこの不機嫌なやつに1杯だ。これで酔いがさめなきゃ、何をやってもだめだね。\n\nあ、それと……これに触ったら手を洗いな。あと、目に入れないようにね。", nil, nil, 0xfd1d5424, 0x84763129, 0xa533783b, nil, nil, "...mm" },
  [95961] = { "出かけたまま", "Powderfuse PortでGray Dawnbrightを見つける。", "<Tessaの赤ん坊は大声で泣き続けている。>\n\n眠いわけでもないみたい。ああ……みんな簡単そうにやってみせるのに。この子のお父さんは、いつもこの子をあやす方法を知ってるの。早く帰ってきてくれたらいいのに。\n\n{name}、こんなことを頼むのは心苦しいけど、何があの人をこんなに遅らせているのか見てきてもらえないかしら？しばらく前に出かけたんだけど、もうとっくに戻っているはずなのよ。Emmaはあの人を見るとぱっと明るくなるの。\n\nPowderfuse Portで見つかるはずよ。最近よくあそこに行くみたいだから。私のGrayは見ればすぐわかるわ。お日様みたいに明るく輝いているもの。", nil, nil, 0x8ccc9729, 0x27b9866b, 0x9432dd15, nil, nil, "...mm" },
  [95975] = { "彼女の世界", "Wildflowerを$N1本集め、Farholde KeepにいるTessa Dawnbrightに届ける。", "Tessが、Emmは俺がいないと眠れないって？それで、あんたは二人のためにそこまでしてくれたのか？まったくの他人なのに？くそっ。俺は何を考えてたんだ……\n\nあの子に完璧な世界を約束できなくても、俺はその一部でいなくちゃいけない。明るい未来を望めないなら、俺はいったい何のために戦ってるんだ？\n\n俺がいない間、家族を助けてくれてありがとう、友よ。でも、もう家に帰る時だ。もう1つ頼みを聞いてもらえるなら、花を摘んでTessに届けてくれないか？もうすぐ帰るって伝えてくれ。まずは身なりを整えなきゃな。", nil, nil, 0xcc35dd84, 0xeded6ec0, 0xdd8a0d2e, nil, nil, "...mm" },
  [95981] = { "道の見張り", "SepulcherにいるShadow Priest Allisterのために、Dalaran Wizardを$N1人とDalaran Watcherを$N2人倒してください。", "奴らのペンダントを奪うのは最初の一歩にすぎない。もしKirin Torが本当にDalaranから遺物を絶えず送り込んでいるのなら、元から断たねばならん。\n\nAmbermillの周りの道で、Dalaranの魔術師と監視者を探せ。奴らのせいで、あまりにも長いあいだ我らの国境を自由に行き来されてきた。奴らの数を減らせれば、そもそもこのペンダントがSilverpine Forestに入ってくるのを止められるはずだ。", nil, "Dalaranを囲む障壁が消えてからというもの、Kirin Torは街道をがっちりと押さえている。何かを恐れているのは確かだ。\n\nだが今のところ、理由はどうでもいい。", 0xda0a241c, 0x94f2addc, 0x6d26148a, nil, 0xf9405a42, "...m." },
  [95982] = { "私の知ったことじゃない", "Briny Seafood Stewを$N1個、Powderfuse PortにいるJasper Geartoggleのところへ持って行く。", "みんな、俺が何をしてるかわかってるみたいに、毛むくじゃらの友達をここに置いてきやがる。それで、戻ってきて馬だか狼だか……とにかく連れてきたのが死んでたり逃げてたりしたら、俺のせいにするんだ。俺が何に見える、慈善事業でもやってると思ってんのか？\n\nあんた、飼い葉桶の扱いには慣れてそうだな。この獣どもをおとなしくさせとくのに使えるエサを、ちょいと作ってくれないか？\n\n自分で作れなきゃ、誰かが売ってくれるかもしれない。それと急いでくれ！腹を空かせた動物の暴走なんて、一番ごめんだからな。", nil, nil, 0x16d2f3a7, 0xcc3081d7, 0x6b04a804, nil, nil, "...mm" },
  [95983] = { "ハゲワシのご馳走", "Gnawed SkullをTerral's WatchにいるWatcher Corneliusのところへ持って行く。", "骸骨はひどく損傷している。手足に残る深い跡は、牙や爪の形とおぼろげに一致する。照りつける太陽の下で長い日々を過ごしたせいで、骨は白く脆くもなっている。襲った者の残忍さと天候の厳しさの両方によって、犠牲者の身元はわからなくなっている。\n\n骸骨をまるごと持っていくことはできないが、skullを近くの見張り番のところへ持っていき、何か知っているか確かめることはできる。", nil, nil, 0x3042c70f, 0x440cdf2d, 0x26ed9b26, nil, nil, "...mm" },
  [95984] = { "Striderの歌", "Intact Tallstrider BeakをTerral's WatchにいるWatcher Corneliusのところへ持って行く。", "この跡はライオンのものだ。見たところ、こいつは特に大きい。おそらく近くの群れのボスだろう。\n\n俺の見張り中に人食いライオンがうろついているなんて噂が広まったら、Demarは激怒するだろう。幸い、策がある。\n\n傷ついたtallstriderの鳴き声をまねる笛を作れる。それを使って獣をおびき出すんだ。正しい音を出すには、奴らのbeaksが1つ要るだけだ。平原にはtallstriderがそこらじゅうにいる。beakを取ってきてくれ、さっさと頼むぞ！", nil, nil, 0x37a5cbb4, 0x60e2eaf1, 0xc54240a1, nil, nil, "...mm" },
  [95986] = { "野生の平原の王", "Tallstrider Callを使ってライオンの群れの長を呼び出す。その獣を倒し、Terral's WatchにいるWatcher Corneliusのためにその皮を取ってくる。", "笛ができたぞ、{name}。\n\nこれを持って、ライオンのいる丘の頂上へ行け。ここのすぐ北のはずだ。\n\n着いたら笛を吹け。そうすれば人食いが現れるはずだ。仕留められなかったら戻ってくるなと言うところだが、どのみちお前は死んでいるだろうな。\n\nさあ、行ってこい。骸骨になった我らの友より、うまくやれるか見ものだな。", nil, nil, 0xc62bac87, 0x712e2e61, 0xb8006b01, nil, nil, "...mm" },
  [95988] = { "喉ごしなめらか", "Powderfuse PortにいるInnkeeper Zizplinkのために、Crawler Spittleを$N1個と、Fresh Chum、Goblin Degreaser、Expired Poisonを集める。", "Grayと話したのかい？あいつは笑いの塊みたいなやつだよ。あいつに一番要らないのは、あんたがもう一杯持ってくることさ。ここは宿屋で、酒場じゃないんだ。俺に放り出されてないだけ運がいいよ。\n\nあいつを連れていきたいなら、ご自由に。でも、あの状態じゃどこにも行けやしないと思うね。ちょっとしたゴブリン流の気付け薬でもなきゃな。\n\n俺があんたのちっちゃな友達に「一杯」用意してる間に、このリストの材料を集めてきてくれないか。俺特製のカクテルを飲んだ後でも、まだ酒が欲しいって言うか見ものだね。", nil, nil, 0x5b034a84, 0xc7482903, 0x7e050bd9, nil, nil, "...mm" },
  [95991] = { "お尋ね者：Ghostmaw", "Ghostmaw's FangをFarholde KeepにいるWheatleyのところへ持って行く。", "森の中で馬を運ぶだけでも危ないってのに、謎の幽霊crocoliskが俺の自慢のポニーをかっさらうなんて話まであるんだ！噂じゃ、こいつは普通のcrocの少なくとも3倍はでかいはずだってよ。しかも凶暴さも倍だと！\n\n俺は博打打ちじゃねえ。誰かがこのろくでなしの化け物を始末するまで、馬を危険にさらすつもりはねえ。川沿いでこの害獣を見つけた奴は、また安心して旅ができるとわかるように、その歯を俺のところへ持ってきてくれ。それまで俺はここを動かねえぞ！\n\n-- Wheatley", nil, nil, 0x4beff704, 0x6eb2b2fa, 0xd393462b, nil, nil, "...mm" },
  [95992] = { "お尋ね者：Ghostmaw", "Ghostmaw's FangをRog'marにいるTan'janiのところへ持って行く。", "この辺の水は油断ならねえ。俺のヘッドハンターたちができる限り道を安全にしてるが、俺たちでも捕まえられねえ獣が川をうろついてるのよ。わくわくするだろ？\n\nボスがそいつを片づけろってんで、ちょっとした勝負をやってるのさ。川を見回ってる白いのを見つけて、そいつのfangを持ってこい。このぬるぬるしたcrocoliskを仕留めた奴が、賭け金を総取りだ。ただ、自分が噛みつかれねえようにな、へへっ！\n\n-- Tan'jani", nil, nil, 0x4beff704, 0x52246dda, 0x1da17cbe, nil, nil, "...mm" },
  [95998] = { "大自然", "Sam's Basic Campfireの近くに座り、Boosted Restのバフを受けるまで待って下さい。", "やあどうも、{class}。あんた、冒険者らしい顔つきをしてるね。いいことだ。世の中には、富と栄光を求める俺たちみたいな落ち着きのない連中がもっと必要なんだよ。\n\n外の世界は広くてね、うまくやっていくには荒野で生き抜く術を身につけなきゃならない。あんたのアウトドアの腕前がどれほどかは知らないが、覚える気があるなら、ひとつふたつ教えてやれると思うよ。\n\n火のそばに座って、楽にしてくれ。順を追って説明するよ。", nil, "さて、基本は身につけたから、次は専門技能を学びに行ってはどうだ？ 新しい専門技能にふさわしい、きちんとしたキャンプ用の設備の作り方も教えてくれるだろう。", 0x561c5fa2, 0xd61f22e7, 0xd463b94a, nil, 0x1938d14a, "...m." },
  [95999] = { "お尋ね者：Incinerator Gar'im", "Broken Staff of Incinerator Gar'imをLakeshireのMagistrate Solomonに届けてください。", "指名手配！Incinerator Gar'im。Render's Valleyにおけるオークの侵攻の首謀者。Stonewatch KeepのBlackrockと手を組んでいると見られる。\n\nIncinerator Gar'imに注意せよ。奴とその配下のShadowcastersは極めて危険である。Incinerator Gar'imを討ち取った証をMagistrate Solomonのもとへ届けた勇敢なる者には、相応の報酬が与えられる。", "そこに何を持っている、{race}？", "見事だ、{name}！ Incinerator Gar'imはStonewatch Keepの防備を固めようとしていた。この勝利で、砦を奪還できるかもしれない！", 0xfbb45123, 0x39291674, 0x96bd3b4a, 0x46dc827d, 0xaf05c26e, "....." },
})
